import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Material {
  id: string;
  name: string;
  costPerKg: number;
}

export interface ExtraCost {
  id: string;
  name: string;
  price: number;
}

export interface CalculatorInputs {
  // Job Info
  jobName: string;
  batchQty: number;

  // Material
  materialCost: number;
  materialGrams: number;

  // Time
  timeHours: number;
  timeMinutes: number;

  // Extras
  extras: ExtraCost[];

  // Machine Overhead
  machineCost: number;
  lifespanHours: number;
  powerWatts: number;
  elecRate: number; // Cost per kWh

  // Labor
  laborRate: number; // Hourly
  laborMins: number; // Prep time per batch
  failMargin: number; // Percentage

  // Commercial
  platformFee: number; // Percentage
  taxRate: number; // Percentage
  packagingCost: number; // Per Unit
  shippingCost: number; // Per Unit
  markup: number; // Percentage
}

export interface CostBreakdown {
  material: number;
  energy: number;
  depreciation: number;
  labor: number;
  extras: number;
  failureRisk: number;

  // Commercial
  packaging: number;
  shipping: number;
  tax: number;
  platformFeeAmount: number;

  // Totals
  productionCost: number; // Raw cost to make
  totalCostBasis: number; // Cost + Ops + Tax + Ship
  profit: number;
  finalPrice: number;
}

export interface CalculatedResults {
  unit: CostBreakdown;
  batch: CostBreakdown;
}

export interface HistoryItem {
  id: string;
  date: string;
  name: string;
  inputs: CalculatorInputs;
  finalPrice: number;
}

import { CalculatorInputs, CalculatedResults, CostBreakdown } from '../types';

export const calculateCosts = (inputs: CalculatorInputs): CalculatedResults => {
  const qty = Math.max(1, inputs.batchQty);

  // 1. Base Variable Costs (Total Batch)
  const totalMatCost = (inputs.materialCost / 1000) * inputs.materialGrams;

  const totalHours = inputs.timeHours + (inputs.timeMinutes / 60);

  // Energy: (Watts / 1000) * Hours * Rate
  const totalEnergy = (inputs.powerWatts / 1000) * totalHours * inputs.elecRate;

  // Depreciation: (MachineCost / Lifespan) * Hours
  const totalDepreciation = inputs.lifespanHours > 0 
    ? (inputs.machineCost / inputs.lifespanHours) * totalHours 
    : 0;

  // Labor (Fixed per batch typically, usually prep time)
  const totalLabor = (inputs.laborRate / 60) * inputs.laborMins;

  // Extras
  const totalExtras = inputs.extras.reduce((acc, curr) => acc + curr.price, 0);

  // Subtotal & Failure
  const subtotalProduction = totalMatCost + totalEnergy + totalDepreciation + totalLabor + totalExtras;
  const totalFailure = subtotalProduction * (inputs.failMargin / 100);

  const totalProductionCost = subtotalProduction + totalFailure;

  // --- Per Unit Commercial Logic ---
  const unitProductionCost = totalProductionCost / qty;
  const unitPackaging = inputs.packagingCost;
  const unitShipping = inputs.shippingCost;

  // Tax is usually on the subtotal of (Production + Packaging)
  const unitTax = (unitProductionCost + unitPackaging) * (inputs.taxRate / 100);

  const unitTotalCostBasis = unitProductionCost + unitPackaging + unitTax + unitShipping;

  const unitProfit = unitTotalCostBasis * (inputs.markup / 100);
  const unitPriceBeforePlatform = unitTotalCostBasis + unitProfit;

  // Platform Fee Logic: Price = Target / (1 - Fee%)
  let unitFinalPrice = 0;
  let unitPlatformFee = 0;

  if (inputs.platformFee < 100) {
    unitFinalPrice = unitPriceBeforePlatform / (1 - (inputs.platformFee / 100));
    unitPlatformFee = unitFinalPrice - unitPriceBeforePlatform;
  } else {
    // Avoid division by zero or negative
    unitFinalPrice = 0; 
  }

  // --- Construct Unit Result ---
  const unitResult: CostBreakdown = {
    material: totalMatCost / qty,
    energy: totalEnergy / qty,
    depreciation: totalDepreciation / qty,
    labor: totalLabor / qty,
    extras: totalExtras / qty,
    failureRisk: totalFailure / qty,
    productionCost: unitProductionCost,
    packaging: unitPackaging,
    shipping: unitShipping,
    tax: unitTax,
    platformFeeAmount: unitPlatformFee,
    totalCostBasis: unitTotalCostBasis,
    profit: unitProfit,
    finalPrice: unitFinalPrice
  };

  // --- Construct Batch Result ---
  const batchResult: CostBreakdown = {
    material: totalMatCost,
    energy: totalEnergy,
    depreciation: totalDepreciation,
    labor: totalLabor,
    extras: totalExtras,
    failureRisk: totalFailure,
    productionCost: totalProductionCost,
    packaging: unitPackaging * qty,
    shipping: unitShipping * qty,
    tax: unitTax * qty,
    platformFeeAmount: unitPlatformFee * qty,
    totalCostBasis: unitTotalCostBasis * qty,
    profit: unitProfit * qty,
    finalPrice: unitFinalPrice * qty
  };

  return { unit: unitResult, batch: batchResult };
};

export const parseGCode = (text: string) => {
  const result = {
    hours: 0,
    minutes: 0,
    grams: 0,
    found: false
  };

  // Regex Patterns
  // Bambu: "; total estimated time: 11h 36m 26s"
  // Prusa: "; estimated printing time = 5h 23m 10s"
  const timeRegexBambu = /total estimated time\s*[:=]\s*(?:(\d+)d\s*)?(?:(\d+)h\s*)?(?:(\d+)m\s*)?/;
  const timeRegexPrusa = /estimated printing time\s*=\s*(?:(\d+)d\s*)?(?:(\d+)h\s*)?(?:(\d+)m\s*)?/;

  // Bambu: "; total filament weight [g] : 297.61"
  // Prusa: "; filament used [g] = 297.61"
  const weightRegexBambu = /total filament weight \[g\]\s*[:=]\s*(\d+\.?\d*)/;
  const weightRegexPrusa = /filament used \[g\]\s*=\s*(\d+\.?\d*)/;

  // Time
  let timeMatch = text.match(timeRegexBambu);
  if (!timeMatch) timeMatch = text.match(timeRegexPrusa);

  if (timeMatch) {
    let d = parseInt(timeMatch[1] || '0');
    let h = parseInt(timeMatch[2] || '0');
    let m = parseInt(timeMatch[3] || '0');
    h += d * 24; 

    result.hours = h;
    result.minutes = m;
    result.found = true;
  }

  // Weight
  let weightMatch = text.match(weightRegexBambu);
  if (!weightMatch) weightMatch = text.match(weightRegexPrusa);

  if (weightMatch) {
    result.grams = parseFloat(weightMatch[1]);
    result.found = true;
  }

  return result;
};

import { initializeApp } from "firebase/app";
import { getFirestore, collection, addDoc, getDocs, query, orderBy, limit, Timestamp } from "firebase/firestore";
import { HistoryItem } from "../types";

// --- CONFIGURATION ---
// Replace these with your actual Vercel Environment Variables or Firebase Config
// For now, we use a dummy config. The service will gracefully fallback to localStorage
// if the apiKey is missing or invalid.
const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY || "", 
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID
};

let db: any = null;
let useLocalStorage = true;

try {
  if (firebaseConfig.apiKey) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    useLocalStorage = false;
    console.log("Firebase initialized successfully");
  } else {
    console.warn("Firebase config missing. Using LocalStorage.");
  }
} catch (error) {
  console.error("Error initializing Firebase, falling back to LocalStorage", error);
  useLocalStorage = true;
}

const COLLECTION_NAME = "print_jobs";
const LOCAL_STORAGE_KEY = "bambuCalc_History";

export const saveJob = async (item: Omit<HistoryItem, 'id'>): Promise<HistoryItem> => {
  const finalItem: HistoryItem = {
    ...item,
    id: Date.now().toString(), // Temp ID
  };

  if (useLocalStorage) {
    const existing = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    existing.unshift(finalItem);
    if (existing.length > 50) existing.pop();
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(existing));
    return finalItem;
  } else {
    try {
      const docRef = await addDoc(collection(db, COLLECTION_NAME), {
        ...item,
        createdAt: Timestamp.now()
      });
      return { ...item, id: docRef.id };
    } catch (e) {
      console.error("Firebase save failed:", e);
      // Fallback
      return saveJobLocal(finalItem);
    }
  }
};

const saveJobLocal = (item: HistoryItem): HistoryItem => {
    const existing = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    existing.unshift(item);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(existing));
    return item;
}

export const getJobs = async (): Promise<HistoryItem[]> => {
  if (useLocalStorage) {
    return JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
  } else {
    try {
      const q = query(collection(db, COLLECTION_NAME), orderBy("createdAt", "desc"), limit(20));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })) as unknown as HistoryItem[];
    } catch (e) {
      console.error("Firebase fetch failed:", e);
      return JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    }
  }
};

import React from 'react';
import clsx from 'clsx';

interface InputGroupProps extends React.InputHTMLAttributes<HTMLInputElement> {
  label: string;
  prefix?: string;
  suffix?: string;
  hint?: string;
}

export const InputGroup: React.FC<InputGroupProps> = ({ 
  label, prefix, suffix, hint, className, ...props 
}) => {
  return (
    <div className="mb-4">
      <label className="block text-xs font-semibold text-gray-500 mb-1.5 uppercase tracking-wide">
        {label}
      </label>
      <div className="relative flex items-center">
        {prefix && (
          <span className="absolute left-3 text-gray-400 text-sm pointer-events-none">
            {prefix}
          </span>
        )}
        <input
          {...props}
          className={clsx(
            "w-full bg-white border border-gray-200 text-gray-900 text-sm rounded-lg focus:ring-brand-500 focus:border-brand-500 block p-2.5 transition-all",
            prefix && "pl-8",
            suffix && "pr-10",
