    setIsSaving(true);
    const newItem = {
        date: new Date().toLocaleDateString(),
        name: inputs.jobName,
        inputs: inputs,
        finalPrice: results.unit.finalPrice * inputs.batchQty // Total Price for history listing
    };

    await saveJob(newItem);
    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

