                                <div className="flex justify-between text-xs text-red-400">
                                    <span>+ Platform Fee</span>
                                    <span>{currency(activeResult.platformFeeAmount)}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-between items-center text-white font-bold pt-2">
                             <span>Cost Basis</span>
                             <span>{currency(activeResult.totalCostBasis)}</span>
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="bg-slate-800 p-6 border-t border-slate-700">
                         <div className="text-center mb-6">
                            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-1">Recommended Price</p>
                            <div className="text-4xl font-extrabold text-white tracking-tight">
                                {currency(activeResult.finalPrice)}
                            </div>
                            <div className="text-brand-500 font-bold text-sm mt-1">
                                {currency(activeResult.profit)} Profit
                            </div>
                         </div>

                         <button 
                            onClick={handleSave}
                            disabled={isSaving}
                            className="w-full bg-brand-600 hover:bg-brand-500 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-900/50 mb-3 disabled:opacity-50"
                        >
                            {isSaving ? <RefreshCw className="animate-spin" size={20} /> : <Save size={20} />}
                            Save to History
                         </button>
                         <button 
                             onClick={() => {
                                 navigator.clipboard.writeText(`Quote: ${inputs.jobName}\nPrice: ${currency(activeResult.finalPrice)}`);
                                 alert('Copied to clipboard');
                             }}
                             className="w-full bg-slate-700 hover:bg-slate-600 text-white font-medium py-3 rounded-xl flex items-center justify-center gap-2 transition-all"
                         >
                            <Copy size={18} /> Copy Quote
                         </button>
                    </div>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, ExtraCost } from './types';
import { DEFAULT_INPUTS } from './constants';
import { calculateCosts } from './services/calculatorService';
import { parseGCode } from './services/gcodeService';
import { saveJob, getJobs } from './services/firebase';
import { InputGroup } from './components/InputGroup';
import { SummaryChart } from './components/SummaryChart';
import { HistoryPanel } from './components/HistoryPanel';
import { 
  Upload, Printer, Zap, DollarSign, Package, TrendingUp, 
  Save, Copy, RefreshCw, Box, Layers, Trash2
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  const [inputs, setInputs] = useState<CalculatorInputs>(DEFAULT_INPUTS);
  // FIX: Initialize with calculated values immediately so fields are never undefined
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(DEFAULT_INPUTS));
  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // --- Calculations ---
  useEffect(() => {
    const res = calculateCosts(inputs);
    setResults(res);
  }, [inputs]);

  // --- Load History ---
  useEffect(() => {
    getJobs().then(setHistory);
  }, []);

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number) => {
    setInputs(prev => ({
      ...prev,
      [field]: typeof value === 'string' ? (value === '' ? 0 : parseFloat(value)) : value
    }));
  };

  const addExtra = () => {
    const newExtra: ExtraCost = {
      id: Date.now().toString(),
      name: 'New Item',
      price: 0
    };
    setInputs(prev => ({ ...prev, extras: [...prev.extras, newExtra] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => 
        ex.id === id ? { ...ex, [field]: field === 'price' ? parseFloat(val) : val } : ex
      )
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target?.result as string;
        const parsed = parseGCode(text);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
            alert(`Parsed: ${parsed.grams}g, ${parsed.hours}h ${parsed.minutes}m`);
        } else {
            alert('Could not find specific time/weight data in this file. Try a Bambu or Prusa G-Code file.');
        }
    };
    reader.readAsText(file);
  };

  // --- Persistence ---
  const handleSave = async () => {
    setIsSaving(true);
    const newItem = {
        date: new Date().toLocaleDateString(),
        name: inputs.jobName,
        inputs: inputs,
        finalPrice: results.unit.finalPrice * inputs.batchQty // Total Price for history listing
    };

    await saveJob(newItem);
    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleLoad = (item: HistoryItem) => {
      setInputs(item.inputs);
      window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // --- Display Helpers ---
  const activeResult = viewMode === 'unit' ? results.unit : results.batch;

  // FIX: Handle undefined values safely
  const currency = (val: number | undefined) => `₱${(val || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="bg-brand-600 text-white p-1.5 rounded-lg">
                <Printer size={20} />
            </div>
            <h1 className="text-lg font-bold text-gray-900 tracking-tight">3D Print <span className="text-brand-600">Command</span></h1>
            <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full font-bold uppercase tracking-wider">Pro</span>
          </div>
          <button onClick={() => setInputs(DEFAULT_INPUTS)} className="text-xs font-medium text-gray-500 hover:text-red-500 transition-colors">
            Reset
          </button>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 grid grid-cols-1 lg:grid-cols-12 gap-8">

        {/* LEFT COLUMN - INPUTS */}
        <div className="lg:col-span-8 space-y-8">

            {/* Drop Zone */}
            <div 
                onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                onClick={() => document.getElementById('fileUpload')?.click()}
                className={clsx(
                    "border-2 border-dashed rounded-2xl p-8 text-center transition-all cursor-pointer group",
                    dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 hover:bg-gray-50 bg-white"
                )}
            >
                <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt" />
                <div className="w-12 h-12 bg-blue-50 text-blue-500 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:scale-110 transition-transform">
                    <Upload size={24} />
                </div>
                <h3 className="font-semibold text-gray-900">Import G-Code File</h3>
                <p className="text-sm text-gray-500 mt-1">Drag & drop or click to upload</p>
            </div>

            {/* Section 1: Job Specs */}
            <section className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-gray-100 bg-gray-50 flex items-center gap-2">
                    <Box size={16} className="text-gray-400" />
                    <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">01 // Job Specifications</h2>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="md:col-span-2">
                        <InputGroup label="Job Name" placeholder="e.g. Iron Man Helmet" value={inputs.jobName} onChange={(e) => handleInputChange('jobName', e.target.value)} />
                    </div>
                    <div>
                        <InputGroup label="Batch Quantity" type="number" suffix="pcs" value={inputs.batchQty} onChange={(e) => handleInputChange('batchQty', e.target.value)} />
                    </div>
                    <div>
                         {/* Material Selector Placeholder - Could expand to a full component */}
                         <InputGroup label="Material Cost (1kg)" type="number" prefix="₱" value={inputs.materialCost} onChange={(e) => handleInputChange('materialCost', e.target.value)} />
                    </div>
                    <div>
                        <InputGroup label="Filament Used" type="number" suffix="g" value={inputs.materialGrams} onChange={(e) => handleInputChange('materialGrams', e.target.value)} />
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <InputGroup label="Hours" type="number" value={inputs.timeHours} onChange={(e) => handleInputChange('timeHours', e.target.value)} />
                        <InputGroup label="Minutes" type="number" value={inputs.timeMinutes} onChange={(e) => handleInputChange('timeMinutes', e.target.value)} />
                    </div>

                    {/* Extras */}
                    <div className="md:col-span-2 bg-gray-50 rounded-xl p-4">
                        <div className="flex justify-between items-center mb-3">
                            <span className="text-xs font-bold text-gray-500 uppercase">Hardware & Extras</span>
                            <button onClick={addExtra} className="text-xs text-brand-600 font-bold hover:underline">+ Add Item</button>
                        </div>
                        {inputs.extras.length === 0 && <div className="text-xs text-gray-400 italic">No extra items added.</div>}
                        <div className="space-y-2">
                            {inputs.extras.map(extra => (
                                <div key={extra.id} className="flex gap-2">
                                    <input className="flex-1 text-sm border rounded px-2 py-1" value={extra.name} onChange={(e) => updateExtra(extra.id, 'name', e.target.value)} />
                                    <input className="w-24 text-sm border rounded px-2 py-1" type="number" value={extra.price} onChange={(e) => updateExtra(extra.id, 'price', e.target.value)} />
                                    <button onClick={() => removeExtra(extra.id)} className="text-red-400 hover:text-red-600"><Trash2 size={16}/></button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </section>

            {/* Section 2: Factory Overhead */}
            <section className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-gray-100 bg-gray-50 flex items-center gap-2">
                    <Zap size={16} className="text-gray-400" />
                    <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">02 // Factory Overhead</h2>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
                    <InputGroup label="Machine Cost" prefix="₱" value={inputs.machineCost} onChange={(e) => handleInputChange('machineCost', e.target.value)} />
                    <InputGroup label="Lifespan" suffix="hrs" value={inputs.lifespanHours} onChange={(e) => handleInputChange('lifespanHours', e.target.value)} />
                    <InputGroup label="Power Draw" suffix="W" value={inputs.powerWatts} onChange={(e) => handleInputChange('powerWatts', e.target.value)} />
                    <InputGroup label="Elec. Rate" prefix="₱" suffix="/kWh" value={inputs.elecRate} onChange={(e) => handleInputChange('elecRate', e.target.value)} />
                    <InputGroup label="Labor Rate" prefix="₱" suffix="/hr" value={inputs.laborRate} onChange={(e) => handleInputChange('laborRate', e.target.value)} />
                    <InputGroup label="Prep Time" suffix="min" value={inputs.laborMins} onChange={(e) => handleInputChange('laborMins', e.target.value)} />
                </div>
            </section>

             {/* Section 3: Commercial */}
             <section className="bg-white rounded-2xl border border-gray-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-gray-100 bg-gray-50 flex items-center gap-2">
                    <TrendingUp size={16} className="text-gray-400" />
                    <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">03 // Commercial</h2>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-3 gap-6">
                    <InputGroup label="Fail Margin" suffix="%" value={inputs.failMargin} onChange={(e) => handleInputChange('failMargin', e.target.value)} />
                    <InputGroup label="Platform Fee" suffix="%" value={inputs.platformFee} onChange={(e) => handleInputChange('platformFee', e.target.value)} />
                    <InputGroup label="Tax Rate" suffix="%" value={inputs.taxRate} onChange={(e) => handleInputChange('taxRate', e.target.value)} />
                    <InputGroup label="Packaging" prefix="₱" value={inputs.packagingCost} onChange={(e) => handleInputChange('packagingCost', e.target.value)} />
                    <InputGroup label="Shipping" prefix="₱" value={inputs.shippingCost} onChange={(e) => handleInputChange('shippingCost', e.target.value)} />
                    <div className="relative">
                        <InputGroup className="border-brand-300 bg-green-50 focus:ring-brand-500" label="Markup Goal" suffix="%" value={inputs.markup} onChange={(e) => handleInputChange('markup', e.target.value)} />
                    </div>
                </div>
            </section>

            {/* History Section */}
            <section className="pt-8">
                 <h3 className="text-lg font-bold text-gray-900 mb-4">Job History</h3>
                 <HistoryPanel items={history} onLoad={handleLoad} onDelete={() => {}} />
            </section>
        </div>

        {/* RIGHT COLUMN - HUD */}
        <div className="lg:col-span-4 space-y-6">
            <div className="sticky top-24">
                <div className="bg-slate-900 text-white rounded-3xl shadow-xl overflow-hidden border border-slate-800">

                    {/* HUD Header & Toggle */}
                    <div className="p-6 pb-0">
                        <div className="flex items-center justify-between mb-4">
                            <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Pricing Analysis</span>
                            <div className="flex bg-slate-800 p-1 rounded-lg">
                                <button 
                                    onClick={() => setViewMode('unit')}
                                    className={clsx("px-3 py-1 text-xs font-bold rounded-md transition-all", viewMode === 'unit' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                >
                                    Per Unit
                                </button>
                                <button 
                                    onClick={() => setViewMode('batch')}
                                    className={clsx("px-3 py-1 text-xs font-bold rounded-md transition-all", viewMode === 'batch' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                >
                                    Total Batch
                                </button>
                            </div>
                        </div>

                        {/* Chart Area */}
                        <div className="flex justify-center py-2">
                           <SummaryChart data={activeResult} currency={currency} />
                        </div>
                    </div>

                    {/* Breakdown List */}
                    <div className="p-6 space-y-3">
                        <div className="flex justify-between text-sm text-slate-400">
                            <div className="flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-blue-500"></span> Material
                            </div>
                            <span>{currency(activeResult.material)}</span>
                        </div>
                        <div className="flex justify-between text-sm text-slate-400">
                            <div className="flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-purple-500"></span> Labor
                            </div>
                            <span>{currency(activeResult.labor)}</span>
                        </div>
                        <div className="flex justify-between text-sm text-slate-400">
                            <div className="flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-yellow-500"></span> Energy/Mach
                            </div>
                            <span>{currency((activeResult.energy || 0) + (activeResult.depreciation || 0))}</span>
                        </div>
                        <div className="flex justify-between text-sm text-slate-400">
                             <div className="flex items-center gap-2">
                                <span className="w-2 h-2 rounded-full bg-slate-500"></span> Risk/Extras
                            </div>
                            <span>{currency((activeResult.failureRisk || 0) + (activeResult.extras || 0))}</span>
                        </div>

                        <div className="border-t border-slate-800 my-4 pt-4">
                            <div className="flex justify-between items-center text-white font-medium">
                                <span>Production Cost</span>
                                <span>{currency(activeResult.productionCost)}</span>
                            </div>

                            <div className="space-y-1 mt-2 pl-4 border-l-2 border-slate-800">
                                <div className="flex justify-between text-xs text-slate-500">
                                    <span>+ Packaging</span>
                                    <span>{currency(activeResult.packaging)}</span>
                                </div>
                                <div className="flex justify-between text-xs text-slate-500">
                                    <span>+ Tax</span>
                                    <span>{currency(activeResult.tax)}</span>
                                </div>
                                <div className="flex justify-between text-xs text-slate-500">
                                    <span>+ Shipping</span>
                                    <span>{currency(activeResult.shipping)}</span>
                                </div>
                                <div className="flex justify-between text-xs text-red-400">
                                    <span>+ Platform Fee</span>
                                    <span>{currency(activeResult.platformFeeAmount)}</span>
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-between items-center text-white font-bold pt-2">
                             <span>Cost Basis</span>
                             <span>{currency(activeResult.totalCostBasis)}</span>
                        </div>
                    </div>

                    {/* Footer Actions */}
                    <div className="bg-slate-800 p-6 border-t border-slate-700">
                         <div className="text-center mb-6">
                            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-1">Recommended Price</p>
                            <div className="text-4xl font-extrabold text-white tracking-tight">
                                {currency(activeResult.finalPrice)}
                            </div>
                            <div className="text-brand-500 font-bold text-sm mt-1">
                                {currency(activeResult.profit)} Profit
                            </div>
                         </div>

                         <button 
                            onClick={handleSave}
                            disabled={isSaving}
                            className="w-full bg-brand-600 hover:bg-brand-500 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-900/50 mb-3 disabled:opacity-50"
                        >
                            {isSaving ? <RefreshCw className="animate-spin" size={20} /> : <Save size={20} />}
                            Save to History
                         </button>
                         <button 
                             onClick={() => {
                                 navigator.clipboard.writeText(`Quote: ${inputs.jobName}\nPrice: ${currency(activeResult.finalPrice)}`);
                                 alert('Copied to clipboard');
                             }}
                             className="w-full bg-slate-700 hover:bg-slate-600 text-white font-medium py-3 rounded-xl flex items-center justify-center gap-2 transition-all"
                         >
                            <Copy size={18} /> Copy Quote
                         </button>
                    </div>
                </div>
            </div>
        </div>

      </div>
    </div>
  );
}

export default App;

import React from 'react';
import { HistoryItem } from '../types';
import { Clock, RotateCcw, Trash2 } from 'lucide-react';

interface HistoryPanelProps {
  items: HistoryItem[];
  onLoad: (item: HistoryItem) => void;
  onDelete: (item: HistoryItem) => void; // Placeholder for future use
}

export const HistoryPanel: React.FC<HistoryPanelProps> = ({ items, onLoad }) => {
  if (items.length === 0) {
    return (
      <div className="text-center py-8 border-2 border-dashed border-gray-200 rounded-xl">
        <p className="text-gray-400 text-sm">No saved jobs found.</p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
        {items.map((job) => (
            <div 
                key={job.id}
                onClick={() => onLoad(job)}
                className="group flex items-center justify-between p-4 bg-white border border-gray-200 rounded-xl hover:border-brand-500 hover:shadow-sm cursor-pointer transition-all"
            >
                <div>
                    <h4 className="font-semibold text-gray-800 text-sm">{job.name || 'Untitled Job'}</h4>
                    <div className="flex items-center gap-2 mt-1 text-xs text-gray-400">
                        <span className="flex items-center gap-1">
                            <Clock size={10} /> {job.date}
                        </span>
                        <span>•</span>
                        <span>{job.inputs.batchQty} pcs</span>
                    </div>
                </div>
                <div className="text-right">
                    <div className="text-brand-600 font-bold text-sm">
                        ₱{(job.finalPrice || 0).toLocaleString(undefined, { maximumFractionDigits: 2 })}
                    </div>
                    <button className="text-xs text-gray-400 opacity-0 group-hover:opacity-100 flex items-center gap-1 ml-auto mt-1 hover:text-brand-600 transition-opacity">
                        <RotateCcw size={10} /> Load
                    </button>
                </div>
            </div>
        ))}
    </div>
  );
};

import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from 'recharts';
import { CostBreakdown } from '../types';
import { COLORS } from '../constants';

interface SummaryChartProps {
  data: CostBreakdown;
  currency: (val: number) => string;
}

export const SummaryChart: React.FC<SummaryChartProps> = ({ data, currency }) => {
  const chartData = [
    { name: 'Material', value: data.material || 0, color: COLORS.material },
    { name: 'Labor', value: data.labor || 0, color: COLORS.labor },
    { name: 'Energy/Mach', value: (data.energy || 0) + (data.depreciation || 0), color: COLORS.energy },
    { name: 'Overhead/Risk', value: (data.failureRisk || 0) + (data.extras || 0), color: COLORS.overhead },
    { name: 'Profit', value: data.profit || 0, color: COLORS.profit },
  ].filter(d => d.value > 0);

  const marginPercent = data.finalPrice > 0 
    ? ((data.profit / data.finalPrice) * 100).toFixed(1) 
    : '0';

  return (
    <div className="h-48 w-full relative">
      <ResponsiveContainer width="100%" height="100%">
        <PieChart>
          <Pie
            data={chartData}
            cx="50%"
            cy="50%"
            innerRadius={50}
            outerRadius={75}
            paddingAngle={2}
            dataKey="value"
          >
            {chartData.map((entry, index) => (
              <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
            ))}
          </Pie>
          <Tooltip 
            formatter={(value: number) => currency(value)}
            contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgba(0,0,0,0.1)' }}
          />
        </PieChart>
      </ResponsiveContainer>
      <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none">
        <span className="text-[10px] text-gray-400 uppercase tracking-widest font-bold">Margin</span>
        <span className="text-xl font-extrabold text-brand-600">{marginPercent}%</span>
      </div>
    </div>
  );
};

payload.text:
**Addressing Input Group UX**

