export interface Material {
  id: string;
  name: string;
  costPerKg: number;
}

export interface ExtraCost {
  id: string;
  name: string;
  price: number | string;
}

export interface CalculatorInputs {
  // Job Info
  jobName: string;
  batchQty: number | string;

  // Material
  materialCost: number | string;
  materialGrams: number | string;

  // Time
  timeHours: number | string;
  timeMinutes: number | string;

  // Extras
  extras: ExtraCost[];

  // Machine Overhead
  machineCost: number | string;
  lifespanHours: number | string;
  powerWatts: number | string;
  elecRate: number | string; // Cost per kWh

  // Labor
  laborRate: number | string; // Hourly
  laborMins: number | string; // Prep time per batch
  failMargin: number | string; // Percentage

  // Commercial
  platformFee: number | string; // Percentage
  taxRate: number | string; // Percentage
  packagingCost: number | string; // Per Unit
  shippingCost: number | string; // Per Unit
  markup: number | string; // Percentage
}

export interface CostBreakdown {
  material: number;
  energy: number;
  depreciation: number;
  labor: number;
  extras: number;
  failureRisk: number;

  // Commercial
  packaging: number;
  shipping: number;
  tax: number;
  platformFeeAmount: number;

  // Totals
  productionCost: number; // Raw cost to make
  totalCostBasis: number; // Cost + Ops + Tax + Ship
  profit: number;
  finalPrice: number;
}

export interface CalculatedResults {
  unit: CostBreakdown;
  batch: CostBreakdown;
}

export interface HistoryItem {
  id: string;
  date: string;
  name: string;
  inputs: CalculatorInputs;
  finalPrice: number;
}

import { CalculatorInputs, CalculatedResults, CostBreakdown } from '../types';

const toNumber = (val: number | string | undefined): number => {
    if (typeof val === 'number') return val;
    if (!val) return 0;
    const num = parseFloat(val);
    return isNaN(num) ? 0 : num;
};

export const calculateCosts = (inputs: CalculatorInputs): CalculatedResults => {
  const qty = Math.max(1, toNumber(inputs.batchQty));

  // 1. Base Variable Costs (Total Batch)
  const totalMatCost = (toNumber(inputs.materialCost) / 1000) * toNumber(inputs.materialGrams);

  const totalHours = toNumber(inputs.timeHours) + (toNumber(inputs.timeMinutes) / 60);

  // Energy: (Watts / 1000) * Hours * Rate
  const totalEnergy = (toNumber(inputs.powerWatts) / 1000) * totalHours * toNumber(inputs.elecRate);

  // Depreciation: (MachineCost / Lifespan) * Hours
  const lifespan = toNumber(inputs.lifespanHours);
  const totalDepreciation = lifespan > 0 
    ? (toNumber(inputs.machineCost) / lifespan) * totalHours 
    : 0;

  // Labor (Fixed per batch typically, usually prep time)
  const totalLabor = (toNumber(inputs.laborRate) / 60) * toNumber(inputs.laborMins);

  // Extras
  const totalExtras = inputs.extras.reduce((acc, curr) => acc + toNumber(curr.price), 0);

  // Subtotal & Failure
  const subtotalProduction = totalMatCost + totalEnergy + totalDepreciation + totalLabor + totalExtras;
  const totalFailure = subtotalProduction * (toNumber(inputs.failMargin) / 100);

  const totalProductionCost = subtotalProduction + totalFailure;

  // --- Per Unit Commercial Logic ---
  const unitProductionCost = totalProductionCost / qty;
  const unitPackaging = toNumber(inputs.packagingCost);
  const unitShipping = toNumber(inputs.shippingCost);

  // Tax is usually on the subtotal of (Production + Packaging)
  const unitTax = (unitProductionCost + unitPackaging) * (toNumber(inputs.taxRate) / 100);

  const unitTotalCostBasis = unitProductionCost + unitPackaging + unitTax + unitShipping;

  const unitProfit = unitTotalCostBasis * (toNumber(inputs.markup) / 100);
  const unitPriceBeforePlatform = unitTotalCostBasis + unitProfit;

  // Platform Fee Logic: Price = Target / (1 - Fee%)
  let unitFinalPrice = 0;
  let unitPlatformFee = 0;

  const feePercent = toNumber(inputs.platformFee);
  if (feePercent < 100) {
    unitFinalPrice = unitPriceBeforePlatform / (1 - (feePercent / 100));
    unitPlatformFee = unitFinalPrice - unitPriceBeforePlatform;
  } else {
    // Avoid division by zero or negative
    unitFinalPrice = 0; 
  }

  // --- Construct Unit Result ---
  const unitResult: CostBreakdown = {
    material: totalMatCost / qty,
    energy: totalEnergy / qty,
    depreciation: totalDepreciation / qty,
    labor: totalLabor / qty,
    extras: totalExtras / qty,
    failureRisk: totalFailure / qty,
    productionCost: unitProductionCost,
    packaging: unitPackaging,
    shipping: unitShipping,
    tax: unitTax,
    platformFeeAmount: unitPlatformFee,
    totalCostBasis: unitTotalCostBasis,
    profit: unitProfit,
    finalPrice: unitFinalPrice
  };

  // --- Construct Batch Result ---
  const batchResult: CostBreakdown = {
    material: totalMatCost,
    energy: totalEnergy,
    depreciation: totalDepreciation,
    labor: totalLabor,
    extras: totalExtras,
    failureRisk: totalFailure,
    productionCost: totalProductionCost,
    packaging: unitPackaging * qty,
    shipping: unitShipping * qty,
    tax: unitTax * qty,
    platformFeeAmount: unitPlatformFee * qty,
    totalCostBasis: unitTotalCostBasis * qty,
    profit: unitProfit * qty,
    finalPrice: unitFinalPrice * qty
  };

  return { unit: unitResult, batch: batchResult };
};

