import { CalculatorInputs } from '../types';
import { DEFAULT_INPUTS } from '../constants';

const SETTINGS_KEY = 'bambuCalc_Settings';

// Fields we want to remember
const PERSISTENT_FIELDS: (keyof CalculatorInputs)[] = [
  'materialCost',
  'machineCost',
  'lifespanHours',
  'powerWatts',
  'elecRate',
  'laborRate',
  'laborMins',
  'failMargin',
  'platformFee',
  'taxRate',
  'packagingCost',
  'shippingCost',
  'markup'
];

export const loadSettings = (): Partial<CalculatorInputs> => {
  if (typeof window === 'undefined') return {};

  try {
    const saved = localStorage.getItem(SETTINGS_KEY);
    if (!saved) return {};
    return JSON.parse(saved);
  } catch (e) {
    console.error("Failed to load settings", e);
    return {};
  }
};

export const saveSettings = (inputs: CalculatorInputs) => {
  if (typeof window === 'undefined') return;

  const settingsToSave: Partial<CalculatorInputs> = {};

  PERSISTENT_FIELDS.forEach(field => {
    // @ts-ignore
    settingsToSave[field] = inputs[field];
  });

  localStorage.setItem(SETTINGS_KEY, JSON.stringify(settingsToSave));
};

export const mergeWithDefaults = (saved: Partial<CalculatorInputs>): CalculatorInputs => {
  return {
    ...DEFAULT_INPUTS,
    ...saved,
    // Ensure transient fields are reset
    jobName: '',
    batchQty: 1,
    materialGrams: 0,
    timeHours: 0,
    timeMinutes: 0,
    extras: [] 
  };
};

import { initializeApp } from "firebase/app";
import { getFirestore, collection, addDoc, getDocs, deleteDoc, doc, query, orderBy, limit, Timestamp } from "firebase/firestore";
import { HistoryItem } from "../types";

// --- CONFIGURATION ---
const firebaseConfig = {
  apiKey: process.env.NEXT_PUBLIC_FIREBASE_API_KEY || "", 
  authDomain: process.env.NEXT_PUBLIC_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID,
  storageBucket: process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.NEXT_PUBLIC_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.NEXT_PUBLIC_FIREBASE_APP_ID
};

let db: any = null;
let useLocalStorage = true;

try {
  if (firebaseConfig.apiKey) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    useLocalStorage = false;
    console.log("Firebase initialized successfully");
  } else {
    console.warn("Firebase config missing. Using LocalStorage.");
  }
} catch (error) {
  console.error("Error initializing Firebase, falling back to LocalStorage", error);
  useLocalStorage = true;
}

const COLLECTION_NAME = "print_jobs";
const LOCAL_STORAGE_KEY = "bambuCalc_History";

export const saveJob = async (item: Omit<HistoryItem, 'id'>): Promise<HistoryItem> => {
  const finalItem: HistoryItem = {
    ...item,
    id: Date.now().toString(),
  };

  if (useLocalStorage) {
    const existing = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    existing.unshift(finalItem);
    if (existing.length > 50) existing.pop();
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(existing));
    return finalItem;
  } else {
    try {
      const docRef = await addDoc(collection(db, COLLECTION_NAME), {
        ...item,
        createdAt: Timestamp.now()
      });
      return { ...item, id: docRef.id };
    } catch (e) {
      console.error("Firebase save failed:", e);
      return saveJobLocal(finalItem);
    }
  }
};

const saveJobLocal = (item: HistoryItem): HistoryItem => {
    const existing = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    existing.unshift(item);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(existing));
    return item;
}

export const getJobs = async (): Promise<HistoryItem[]> => {
  if (useLocalStorage) {
    return JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
  } else {
    try {
      const q = query(collection(db, COLLECTION_NAME), orderBy("createdAt", "desc"), limit(50));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })) as unknown as HistoryItem[];
    } catch (e) {
      console.error("Firebase fetch failed:", e);
      return JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    }
  }
};

export const deleteJob = async (id: string): Promise<void> => {
  if (useLocalStorage) {
    const existing = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
    const filtered = existing.filter((item: HistoryItem) => item.id !== id);
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(filtered));
  } else {
    try {
      // Note: We are deleting by document ID. If the ID was generated by Date.now() 
      // because of a fallback, this might fail on Firestore, but handles local storage items correctly.
      await deleteDoc(doc(db, COLLECTION_NAME, id));
    } catch (e) {
      console.error("Firebase delete failed, trying local", e);
      // Fallback to local delete in case it was a local item mixed in
      const existing = JSON.parse(localStorage.getItem(LOCAL_STORAGE_KEY) || "[]");
      const filtered = existing.filter((item: HistoryItem) => item.id !== id);
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(filtered));
    }
  }
};

