import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem } from '../types';
import { calculateCosts } from '../services/calculatorService';
import { X, Trash2, Download, TrendingUp, DollarSign, Package, Plus, ShoppingCart, Wallet, CreditCard } from 'lucide-react';
import clsx from 'clsx';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => void;
  onDeleteCapital: (id: string) => void;
  currency: (val: number) => string;
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ 
  isOpen, onClose, history, capitalHistory, 
  onDeleteJob, onAddCapital, onDeleteCapital, currency 
}) => {
  const [activeTab, setActiveTab] = useState<'jobs' | 'capital'>('jobs');

  // New Capital Item State
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');
  const [newItemDate, setNewItemDate] = useState(new Date().toISOString().split('T')[0]);
  const [newItemCategory, setNewItemCategory] = useState<CapitalItem['category']>('Filament');
  const [newItemStore, setNewItemStore] = useState('');

  if (!isOpen) return null;

  // Calculate aggregates
  const stats = useMemo(() => {
    let totalRev = 0;
    let totalProfit = 0;

    history.forEach(job => {
      const res = calculateCosts(job.inputs);
      const revenue = job.finalPrice || 0;
      const profit = res.batch.profit || 0;
      totalRev += revenue;
      totalProfit += profit;
    });

    const totalCapital = capitalHistory.reduce((acc, curr) => acc + (curr.price || 0), 0);
    const netPosition = totalProfit - totalCapital;
    const avgMargin = totalRev > 0 ? (totalProfit / totalRev) * 100 : 0;

    return { totalRev, totalProfit, avgMargin, totalCapital, netPosition };
  }, [history, capitalHistory]);

  const handleAddCapital = () => {
    if (!newItemName || !newItemPrice) return;
    onAddCapital({
      name: newItemName,
      price: parseFloat(newItemPrice),
      date: newItemDate,
      category: newItemCategory,
      store: newItemStore
    });
    // Reset form
    setNewItemName('');
    setNewItemPrice('');
    setNewItemStore('');
  };

  const exportCSV = () => {
    if (activeTab === 'jobs') {
      const headers = ['Date', 'Job Name', 'Qty', 'Material Cost', 'Hours', 'Total Price', 'Est. Profit'];
      const rows = history.map(job => {
        const res = calculateCosts(job.inputs);
        return [
          job.date, `"${job.name}"`, job.inputs.batchQty, job.inputs.materialCost, 
          job.inputs.timeHours, job.finalPrice.toFixed(2), res.batch.profit.toFixed(2)
        ].join(',');
      });
      downloadCSV(headers, rows, 'print_jobs_export.csv');
    } else {
      const headers = ['Date', 'Item Name', 'Category', 'Store', 'Price'];
      const rows = capitalHistory.map(item => {
        return [
          item.date, `"${item.name}"`, item.category, `"${item.store || ''}"`, item.price.toFixed(2)
        ].join(',');
      });
      downloadCSV(headers, rows, 'capital_expenses_export.csv');
    }
  };

  const downloadCSV = (headers: string[], rows: string[], filename: string) => {
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-6xl max-h-[95vh] overflow-hidden flex flex-col shadow-2xl">

        {/* Header */}
