import React, { useState, useEffect, useCallback } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, ExtraCost, CapitalItem } from './types';
import { DEFAULT_INPUTS } from './constants';
import { calculateCosts } from './services/calculatorService';
import { parseGCode } from './services/gcodeService';
import { saveJob, getJobs, deleteJob, saveCapitalItem, getCapitalItems, deleteCapitalItem } from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';
import { InputGroup } from './components/InputGroup';
import { SummaryChart } from './components/SummaryChart';
import { HistoryPanel } from './components/HistoryPanel';
import { DashboardModal } from './components/DashboardModal';
import { 
  Upload, Printer, Zap, DollarSign, Package, TrendingUp, 
  Save, Copy, RefreshCw, Box, Layers, Trash2, LayoutDashboard
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // Initialize state with stored settings + defaults
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });

  // Initialize calculation based on that state
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));

  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]); // New State
  const [dragActive, setDragActive] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);

  // --- Calculations ---
  useEffect(() => {
    const res = calculateCosts(inputs);
    setResults(res);
  }, [inputs]);

  // --- Auto-Save Settings ---
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost,
    inputs.machineCost,
    inputs.lifespanHours,
    inputs.powerWatts,
    inputs.elecRate,
    inputs.laborRate,
    inputs.laborMins,
    inputs.failMargin,
    inputs.platformFee,
    inputs.taxRate,
    inputs.packagingCost,
    inputs.shippingCost,
    inputs.markup
  ]);

  // --- Load Data ---
  useEffect(() => {
    getJobs().then(setHistory);
    getCapitalItems().then(setCapitalHistory); // Load Capital
  }, []);

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number) => {
    setInputs(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const addExtra = () => {
    const newExtra: ExtraCost = {
      id: Date.now().toString(),
      name: 'New Item',
      price: 0
    };
    setInputs(prev => ({ ...prev, extras: [...prev.extras, newExtra] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => 
        ex.id === id ? { ...ex, [field]: val } : ex
      )
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target?.result as string;
        const parsed = parseGCode(text);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
            alert(`Parsed: ${parsed.grams}g, ${parsed.hours}h ${parsed.minutes}m`);
        } else {
            alert('Could not find specific time/weight data in this file. Try a Bambu or Prusa G-Code file.');
        }
    };
    reader.readAsText(file);
  };

  // --- Job Persistence ---
  const handleSave = async () => {
    setIsSaving(true);
    const newItem = {
        date: new Date().toLocaleDateString(),
        name: inputs.jobName,
        inputs: inputs,
        finalPrice: results.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1)
    };

    await saveJob(newItem);
    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleDeleteJob = async (id: string) => {
      await deleteJob(id);
      const updated = await getJobs();
      setHistory(updated);
  }

  // --- Capital Persistence ---
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleLoad = (item: HistoryItem) => {
      setInputs(item.inputs);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setShowDashboard(false); // Close dashboard if open when loading
  };

  // --- Display Helpers ---
  const activeResult = viewMode === 'unit' ? results.unit : results.batch;
