                    values={`(${currency(machineCost)} / ${lifespan}h) × ${printHours.toFixed(2)}h`} 
                    result={currency(results.batch.depreciation)} 
                />
            </Section>

            {/* Labor */}
            <Section title="4. Labor Cost">
                 <Formula label="Formula" text="(Hourly Rate / 60) × Prep Minutes" />
                 <Calculation 
                    values={`(${currency(laborRate)} / 60) × ${laborMins}m`} 
                    result={currency(results.batch.labor)} 
