import React, { useState, useEffect, useCallback } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, ExtraCost, CapitalItem } from './types';
import { DEFAULT_INPUTS } from './constants';
import { calculateCosts } from './services/calculatorService';
import { parseGCode } from './services/gcodeService';
import { saveJob, getJobs, deleteJob, saveCapitalItem, getCapitalItems, deleteCapitalItem } from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';
import { InputGroup } from './components/InputGroup';
import { SummaryChart } from './components/SummaryChart';
import { HistoryPanel } from './components/HistoryPanel';
import { DashboardModal } from './components/DashboardModal';
import { MathModal } from './components/MathModal';
import { 
  Upload, Printer, Zap, DollarSign, Package, TrendingUp, 
  Save, Copy, RefreshCw, Box, Layers, Trash2, LayoutDashboard,
  ChevronLeft, ChevronRight, History, Calculator, Link
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // Initialize state with stored settings + defaults
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });

  // Initialize calculation based on that state
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));

  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);
  const [showMathModal, setShowMathModal] = useState(false);

  // Sidebar State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // --- Calculations ---
  useEffect(() => {
    const res = calculateCosts(inputs);
    setResults(res);
  }, [inputs]);

  // --- Auto-Save Settings ---
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost,
    inputs.machineCost,
    inputs.lifespanHours,
    inputs.powerWatts,
    inputs.dryerPowerWatts, 
    inputs.elecRate,
    inputs.laborRate,
    inputs.laborMins,
    inputs.failMargin,
    inputs.platformFee,
    inputs.taxRate,
    inputs.packagingCost,
    inputs.shippingCost,
    inputs.markup
  ]);

  // --- Load Data ---
  useEffect(() => {
    getJobs().then(setHistory);
    getCapitalItems().then(setCapitalHistory);
  }, []);

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number | boolean) => {
    setInputs(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const addExtra = () => {
    const newExtra: ExtraCost = {
      id: Date.now().toString(),
      name: 'New Item',
      price: 0
    };
    setInputs(prev => ({ ...prev, extras: [...prev.extras, newExtra] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => 
        ex.id === id ? { ...ex, [field]: val } : ex
      )
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target?.result as string;
        const parsed = parseGCode(text);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
            alert(`Parsed: ${parsed.grams}g, ${parsed.hours}h ${parsed.minutes}m`);
        } else {
            alert('Could not find specific time/weight data in this file. Try a Bambu or Prusa G-Code file.');
        }
    };
    reader.readAsText(file);
  };

  // --- Job Persistence ---
  const handleSave = async () => {
    setIsSaving(true);
    const newItem = {
        date: new Date().toLocaleDateString(),
        name: inputs.jobName,
        inputs: inputs,
        finalPrice: results.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1)
    };

    await saveJob(newItem);
    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleDeleteJob = async (id: string) => {
      await deleteJob(id);
      const updated = await getJobs();
      setHistory(updated);
  }

  // --- Capital Persistence ---
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleLoad = (item: HistoryItem) => {
      setInputs(item.inputs);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setShowDashboard(false); // Close dashboard if open when loading
  };

  // --- Display Helpers ---
  const activeResult = viewMode === 'unit' ? results.unit : results.batch;
  const currency = (val: number | undefined) => `₱${(val || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">

      <DashboardModal 
        isOpen={showDashboard} 
        onClose={() => setShowDashboard(false)} 
        history={history} 
        capitalHistory={capitalHistory}
        onDeleteJob={handleDeleteJob}
        onAddCapital={handleAddCapital}
        onDeleteCapital={handleDeleteCapital}
        currency={currency}
      />

      <MathModal 
        isOpen={showMathModal}
        onClose={() => setShowMathModal(false)}
        inputs={inputs}
        results={results}
        currency={currency}
      />

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm flex-none">
        <div className="max-w-[1920px] mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
             <button 
                onClick={() => setIsSidebarOpen(!isSidebarOpen)}
                className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg transition-colors"
             >
                <History size={20} />
             </button>
             <div className="flex items-center gap-2">
                <div className="bg-brand-600 text-white p-1.5 rounded-lg">
                    <Printer size={20} />
                </div>
                <h1 className="text-lg font-bold text-gray-900 tracking-tight hidden sm:block">3D Print <span className="text-brand-600">Command</span></h1>
             </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
                onClick={() => setShowDashboard(true)}
                className="text-sm font-medium text-gray-600 hover:text-brand-600 hover:bg-gray-100 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
            >
                <LayoutDashboard size={18} /> <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
                onClick={() => setInputs(DEFAULT_INPUTS)} 
                className="text-xs font-bold text-red-500 hover:bg-red-50 px-3 py-2 rounded-lg transition-colors border border-red-100"
            >
                Reset
            </button>
          </div>
        </div>
      </header>

      {/* Main Layout Area */}
      <div className="flex-1 flex overflow-hidden">

        {/* Sidebar */}
        <div 
            className={clsx(
                "bg-white border-r border-gray-200 flex flex-col transition-all duration-300 overflow-hidden relative z-30",
                isSidebarOpen ? "w-72 translate-x-0" : "w-0 -translate-x-full opacity-0"
            )}
        >
            <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
                <h3 className="font-bold text-gray-700 uppercase tracking-wider text-xs flex items-center gap-2">
                    <History size={14} /> Recent Jobs
                </h3>
                <span className="text-[10px] bg-white border border-gray-200 px-2 rounded-full text-gray-500">{history.length}</span>
            </div>
            <div className="flex-1 overflow-y-auto py-4">
                <HistoryPanel items={history} onLoad={handleLoad} onDelete={() => {}} />
