            <div className="p-4 border-t border-gray-200 bg-gray-50">
                <button onClick={() => setShowDashboard(true)} className="w-full py-2 text-xs font-bold text-brand-600 bg-white border border-brand-200 rounded-lg hover:bg-brand-50 transition-colors">
                    View Full History
                </button>
            </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto">
            <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-8">

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">

                    {/* LEFT COLUMN - INPUTS */}
                    <div className="xl:col-span-8 space-y-6">

                        {/* Drop Zone */}
                        <div 
                            onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                            onClick={() => document.getElementById('fileUpload')?.click()}
                            className={clsx(
                                "border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer group",
                                dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 hover:bg-white bg-gray-50/50"
                            )}
                        >
                            <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt" />
                            <div className="flex items-center justify-center gap-3">
                                <div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center">
                                    <Upload size={16} />
