                                {/* Extras */}
                                <div className="md:col-span-2 lg:col-span-4 bg-gray-50 rounded-lg p-3 mt-2 border border-gray-100">
                                    <div className="flex justify-between items-center mb-2">
                                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">Hardware & Extras</span>
                                        <button onClick={addExtra} className="text-[10px] text-brand-600 font-bold hover:underline bg-brand-50 px-2 py-0.5 rounded border border-brand-100">+ Add Item</button>
                                    </div>
                                    <div className="space-y-2">
                                        {inputs.extras.map(extra => (
                                            <div key={extra.id} className="flex gap-2">
                                                <input className="flex-1 text-sm border-gray-300 rounded px-2 py-1" value={extra.name} onChange={(e) => updateExtra(extra.id, 'name', e.target.value)} placeholder="Item name" />
                                                <input className="w-24 text-sm border-gray-300 rounded px-2 py-1" type="number" value={extra.price} onChange={(e) => updateExtra(extra.id, 'price', e.target.value)} placeholder="Price" />
                                                <button onClick={() => removeExtra(extra.id)} className="text-gray-400 hover:text-red-500"><Trash2 size={16}/></button>
                                            </div>
                                        ))}
                                        {inputs.extras.length === 0 && <p className="text-xs text-gray-400 italic">No extras added</p>}
                                    </div>
                                </div>
                            </div>
                        </section>

                        {/* Section 2: Factory Overhead */}
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="px-5 py-3 border-b border-gray-100 bg-gray-50/80 flex items-center gap-2">
                                <Zap size={16} className="text-gray-400" />
                                <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">02 // Factory Overhead</h2>
                            </div>
                            <div className="p-5 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-4">
                                <InputGroup label="Machine Cost" prefix="₱" value={inputs.machineCost} onChange={(e) => handleInputChange('machineCost', e.target.value)} />
                                <InputGroup label="Lifespan" suffix="hrs" value={inputs.lifespanHours} onChange={(e) => handleInputChange('lifespanHours', e.target.value)} />
                                <InputGroup label="Power Draw" suffix="W" value={inputs.powerWatts} onChange={(e) => handleInputChange('powerWatts', e.target.value)} />
                                <InputGroup 
                                    label="Dryer Power" 
                                    suffix="W" 
                                    value={inputs.dryerPowerWatts} 
                                    onChange={(e) => handleInputChange('dryerPowerWatts', e.target.value)}
                                    className="bg-orange-50/30 border-orange-100 focus:border-orange-500"
                                />
                                <InputGroup label="Elec. Rate" prefix="₱" suffix="/kWh" value={inputs.elecRate} onChange={(e) => handleInputChange('elecRate', e.target.value)} />
                                <InputGroup label="Labor Rate" prefix="₱" suffix="/hr" value={inputs.laborRate} onChange={(e) => handleInputChange('laborRate', e.target.value)} />
                                <InputGroup label="Prep Time" suffix="min" value={inputs.laborMins} onChange={(e) => handleInputChange('laborMins', e.target.value)} />
                            </div>
                        </section>

                        {/* Section 3: Commercial */}
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="px-5 py-3 border-b border-gray-100 bg-gray-50/80 flex items-center gap-2">
                                <TrendingUp size={16} className="text-gray-400" />
                                <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">03 // Commercial</h2>
                            </div>
                            <div className="p-5 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                                <InputGroup label="Fail Margin" suffix="%" value={inputs.failMargin} onChange={(e) => handleInputChange('failMargin', e.target.value)} />
                                <InputGroup label="Platform Fee" suffix="%" value={inputs.platformFee} onChange={(e) => handleInputChange('platformFee', e.target.value)} />
                                <InputGroup label="Tax Rate" suffix="%" value={inputs.taxRate} onChange={(e) => handleInputChange('taxRate', e.target.value)} />
                                <InputGroup label="Packaging" prefix="₱" value={inputs.packagingCost} onChange={(e) => handleInputChange('packagingCost', e.target.value)} />
                                <InputGroup label="Shipping" prefix="₱" value={inputs.shippingCost} onChange={(e) => handleInputChange('shippingCost', e.target.value)} />
                                <div className="relative">
                                    <InputGroup className="border-brand-300 bg-green-50 focus:ring-brand-500 font-bold text-brand-700" label="Markup Goal" suffix="%" value={inputs.markup} onChange={(e) => handleInputChange('markup', e.target.value)} />
                                </div>
                            </div>
                        </section>
                    </div>

                    {/* RIGHT COLUMN - HUD */}
                    <div className="xl:col-span-4 space-y-6">
                        <div className="sticky top-6">
                            <div className="bg-slate-900 text-white rounded-2xl shadow-2xl overflow-hidden border border-slate-800 ring-1 ring-white/10">

                                {/* HUD Header & Toggle */}
                                <div className="p-5 pb-0">
                                    <div className="flex items-center justify-between mb-4">
                                        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                                            <div className="w-2 h-2 bg-brand-500 rounded-full animate-pulse"></div>
                                            Live Pricing
                                        </span>
                                        <div className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
                                            <button 
                                                onClick={() => setViewMode('unit')}
                                                className={clsx("px-3 py-1 text-[10px] font-bold rounded-md transition-all uppercase tracking-wide", viewMode === 'unit' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                            >
                                                Per Unit
                                            </button>
                                            <button 
                                                onClick={() => setViewMode('batch')}
                                                className={clsx("px-3 py-1 text-[10px] font-bold rounded-md transition-all uppercase tracking-wide", viewMode === 'batch' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                            >
                                                Total Batch
                                            </button>
                                        </div>
                                    </div>

                                    {/* Chart Area */}
                                    <div className="flex justify-center py-2 h-40">
                                    <SummaryChart data={activeResult} currency={currency} />
                                    </div>
                                </div>

                                {/* Breakdown List */}
                                <div className="px-6 py-4 space-y-2.5">
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-blue-500"></span> Material
                                        </div>
                                        <span>{currency(activeResult?.material)}</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-purple-500"></span> Labor
                                        </div>
                                        <span>{currency(activeResult?.labor)}</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-yellow-500"></span> Energy/Machine
                                        </div>
                                        <span>{currency((activeResult?.energy || 0) + (activeResult?.depreciation || 0))}</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-slate-500"></span> Risk/Extras
                                        </div>
                                        <span>{currency((activeResult?.failureRisk || 0) + (activeResult?.extras || 0))}</span>
                                    </div>

                                    <div className="border-t border-slate-800 my-3 pt-3">
                                        <div className="flex justify-between items-center text-white font-medium text-sm">
                                            <span>Production Cost</span>
                                            <span>{currency(activeResult?.productionCost)}</span>
                                        </div>

                                        <div className="space-y-1 mt-2 pl-3 border-l-2 border-slate-800/50">
                                            <div className="flex justify-between text-[10px] text-slate-500">
                                                <span>+ Packaging</span>
                                                <span>{currency(activeResult?.packaging)}</span>
                                            </div>
                                            <div className="flex justify-between text-[10px] text-slate-500">
                                                <span>+ Tax</span>
                                                <span>{currency(activeResult?.tax)}</span>
                                            </div>
                                            <div className="flex justify-between text-[10px] text-slate-500">
                                                <span>+ Shipping</span>
                                                <span>{currency(activeResult?.shipping)}</span>
                                            </div>
                                            <div className="flex justify-between text-[10px] text-red-400/80">
                                                <span>+ Platform Fee</span>
                                                <span>{currency(activeResult?.platformFeeAmount)}</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex justify-between items-center pt-1">
                                         <div className="text-slate-300 font-bold text-sm">
                                            Cost Basis
                                         </div>
                                         <button 
                                            onClick={() => setShowMathModal(true)}
                                            className="text-[10px] text-brand-400 hover:text-brand-300 hover:underline flex items-center gap-1"
                                         >
                                            <Calculator size={10} /> View Math
                                         </button>
                                    </div>
                                    <div className="text-right text-slate-300 font-bold text-sm">
                                        {currency(activeResult?.totalCostBasis)}
                                    </div>
                                </div>

                                {/* Footer Actions */}
                                <div className="bg-slate-800/80 p-5 border-t border-slate-700 backdrop-blur-sm">
                                    <div className="text-center mb-5">
                                        <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Recommended Price</p>
                                        <div className="text-3xl font-black text-white tracking-tight">
                                            {currency(activeResult?.finalPrice)}
                                        </div>
                                        <div className="text-brand-500 font-bold text-xs mt-1">
                                            {currency(activeResult?.profit)} Profit
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-3">
                                        <button 
                                            onClick={handleSave}
                                            disabled={isSaving}
                                            className="col-span-2 bg-brand-600 hover:bg-brand-500 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-900/20 disabled:opacity-50 text-sm"
                                        >
                                            {isSaving ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                                            Save Job
                                        </button>
                                        <button 
                                            onClick={() => {
                                                const text = `Quote: ${inputs.jobName}\nPrice: ${currency(activeResult?.finalPrice)}`;
                                                navigator.clipboard.writeText(text);
                                                alert('Copied!');
                                            }}
                                            className="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs"
                                        >
                                            <Copy size={14} /> Copy
                                        </button>
                                         <button 
                                            onClick={() => setShowDashboard(true)}
                                            className="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs"
                                        >
                                            <LayoutDashboard size={14} /> Dash
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </div>
      </div>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, ExtraCost, CapitalItem } from './types';
import { DEFAULT_INPUTS } from './constants';
import { calculateCosts } from './services/calculatorService';
import { parseGCode } from './services/gcodeService';
import { saveJob, getJobs, deleteJob, saveCapitalItem, getCapitalItems, deleteCapitalItem } from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';
import { InputGroup } from './components/InputGroup';
import { SummaryChart } from './components/SummaryChart';
import { HistoryPanel } from './components/HistoryPanel';
import { DashboardModal } from './components/DashboardModal';
import { MathModal } from './components/MathModal';
import { 
  Upload, Printer, Zap, DollarSign, Package, TrendingUp, 
  Save, Copy, RefreshCw, Box, Layers, Trash2, LayoutDashboard,
  ChevronLeft, ChevronRight, History, Calculator, Link
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // Initialize state with stored settings + defaults
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });

  // Initialize calculation based on that state
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));

  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);
  const [showMathModal, setShowMathModal] = useState(false);

  // Sidebar State
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);

  // --- Calculations ---
  useEffect(() => {
    const res = calculateCosts(inputs);
    setResults(res);
  }, [inputs]);

  // --- Auto-Save Settings ---
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost,
    inputs.machineCost,
    inputs.lifespanHours,
    inputs.powerWatts,
    inputs.dryerPowerWatts, 
    inputs.elecRate,
    inputs.laborRate,
    inputs.laborMins,
    inputs.failMargin,
    inputs.platformFee,
    inputs.taxRate,
    inputs.packagingCost,
    inputs.shippingCost,
    inputs.markup
  ]);

  // --- Load Data ---
  useEffect(() => {
    getJobs().then(setHistory);
    getCapitalItems().then(setCapitalHistory);
  }, []);

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number | boolean) => {
    setInputs(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const addExtra = () => {
    const newExtra: ExtraCost = {
      id: Date.now().toString(),
      name: 'New Item',
      price: 0
    };
    setInputs(prev => ({ ...prev, extras: [...prev.extras, newExtra] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => 
        ex.id === id ? { ...ex, [field]: val } : ex
      )
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target?.result as string;
        const parsed = parseGCode(text);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
            alert(`Parsed: ${parsed.grams}g, ${parsed.hours}h ${parsed.minutes}m`);
        } else {
            alert('Could not find specific time/weight data in this file. Try a Bambu or Prusa G-Code file.');
        }
    };
    reader.readAsText(file);
  };

  // --- Job Persistence ---
  const handleSave = async () => {
    setIsSaving(true);
    const newItem = {
        date: new Date().toLocaleDateString(),
        name: inputs.jobName,
        inputs: inputs,
        finalPrice: results.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1)
    };

    await saveJob(newItem);
    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleDeleteJob = async (id: string) => {
      await deleteJob(id);
      const updated = await getJobs();
      setHistory(updated);
  }

  // --- Capital Persistence ---
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleLoad = (item: HistoryItem) => {
      setInputs(item.inputs);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setShowDashboard(false); // Close dashboard if open when loading
  };

  // --- Display Helpers ---
  const activeResult = viewMode === 'unit' ? results.unit : results.batch;
  const currency = (val: number | undefined) => `₱${(val || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">

      <DashboardModal 
        isOpen={showDashboard} 
        onClose={() => setShowDashboard(false)} 
        history={history} 
        capitalHistory={capitalHistory}
        onDeleteJob={handleDeleteJob}
        onAddCapital={handleAddCapital}
        onDeleteCapital={handleDeleteCapital}
        currency={currency}
      />

      <MathModal 
        isOpen={showMathModal}
        onClose={() => setShowMathModal(false)}
        inputs={inputs}
        results={results}
        currency={currency}
      />

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm flex-none">
        <div className="max-w-[1920px] mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
             {/* Header Toggle Removed */}
             <div className="flex items-center gap-2">
                <div className="bg-brand-600 text-white p-1.5 rounded-lg">
                    <Printer size={20} />
                </div>
                <h1 className="text-lg font-bold text-gray-900 tracking-tight hidden sm:block">3D Print <span className="text-brand-600">Command</span></h1>
             </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
                onClick={() => setShowDashboard(true)}
                className="text-sm font-medium text-gray-600 hover:text-brand-600 hover:bg-gray-100 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
            >
                <LayoutDashboard size={18} /> <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
                onClick={() => setInputs(DEFAULT_INPUTS)} 
                className="text-xs font-bold text-red-500 hover:bg-red-50 px-3 py-2 rounded-lg transition-colors border border-red-100"
            >
                Reset
            </button>
          </div>
        </div>
      </header>

      {/* Main Layout Area */}
      <div className="flex-1 flex overflow-hidden relative">

        {/* Toggle Button - Floating */}
        <button
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className={clsx(
                "absolute top-4 z-50 bg-white border border-gray-200 shadow-md h-8 w-6 rounded-r-lg flex items-center justify-center text-gray-400 hover:text-brand-600 transition-all duration-300 cursor-pointer",
                isSidebarOpen ? "left-72 border-l-0" : "left-0 border-l-0"
            )}
            title={isSidebarOpen ? "Collapse History" : "Expand History"}
        >
            {isSidebarOpen ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
        </button>

        {/* Sidebar */}
        <div 
            className={clsx(
                "bg-white border-r border-gray-200 flex flex-col transition-all duration-300 overflow-hidden relative z-30",
                isSidebarOpen ? "w-72 translate-x-0" : "w-0 -translate-x-full opacity-0"
            )}
        >
            <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
                <h3 className="font-bold text-gray-700 uppercase tracking-wider text-xs flex items-center gap-2">
                    <History size={14} /> Recent Jobs
                </h3>
                <span className="text-[10px] bg-white border border-gray-200 px-2 rounded-full text-gray-500">{history.length}</span>
            </div>
            <div className="flex-1 overflow-y-auto py-4">
                <HistoryPanel items={history} onLoad={handleLoad} onDelete={() => {}} />
            </div>
            <div className="p-4 border-t border-gray-200 bg-gray-50">
                <button onClick={() => setShowDashboard(true)} className="w-full py-2 text-xs font-bold text-brand-600 bg-white border border-brand-200 rounded-lg hover:bg-brand-50 transition-colors">
                    View Full History
                </button>
            </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto">
            <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-8">

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">

                    {/* LEFT COLUMN - INPUTS */}
                    <div className="xl:col-span-8 space-y-6">

                        {/* Drop Zone */}
                        <div 
                            onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                            onClick={() => document.getElementById('fileUpload')?.click()}
                            className={clsx(
                                "border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer group",
                                dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 hover:bg-white bg-gray-50/50"
                            )}
                        >
                            <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt" />
                            <div className="flex items-center justify-center gap-3">
                                <div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center">
                                    <Upload size={16} />
                                </div>
                                <div className="text-left">
                                    <h3 className="font-semibold text-gray-900 text-sm">Import G-Code</h3>
                                    <p className="text-xs text-gray-500">Drag & drop or click</p>
                                </div>
                            </div>
                        </div>

                        {/* Section 1: Job Specs */}
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="px-5 py-3 border-b border-gray-100 bg-gray-50/80 flex items-center gap-2">
                                <Box size={16} className="text-gray-400" />
                                <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">01 // Job Specifications</h2>
                            </div>
                            <div className="p-5 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-x-4 gap-y-2">
                                <div className="md:col-span-2 lg:col-span-2">
                                    <InputGroup label="Job Name" placeholder="e.g. Iron Man Helmet" value={inputs.jobName} onChange={(e) => handleInputChange('jobName', e.target.value)} />
                                </div>
                                <div>
                                    <InputGroup label="Batch Quantity" type="number" suffix="pcs" value={inputs.batchQty} onChange={(e) => handleInputChange('batchQty', e.target.value)} />
                                </div>
                                <div>
                                    <InputGroup label="Filament Used" type="number" suffix="g" value={inputs.materialGrams} onChange={(e) => handleInputChange('materialGrams', e.target.value)} />
                                </div>

                                <div>
                                    <InputGroup label="Material Cost (1kg)" type="number" prefix="₱" value={inputs.materialCost} onChange={(e) => handleInputChange('materialCost', e.target.value)} />
                                </div>
                                <div>
                                    <InputGroup label="Print Time (Hrs)" type="number" value={inputs.timeHours} onChange={(e) => handleInputChange('timeHours', e.target.value)} />
                                </div>
                                <div>
                                    <InputGroup label="Print Time (Mins)" type="number" value={inputs.timeMinutes} onChange={(e) => handleInputChange('timeMinutes', e.target.value)} />
                                </div>

                                {/* Drying Time Complex */}
                                <div className="lg:col-span-2 p-3 bg-orange-50/30 rounded-lg border border-orange-100">
                                   <div className="flex justify-between items-center mb-2">
                                     <label className="block text-xs font-semibold text-gray-500 uppercase tracking-wide">Drying Time</label>
                                     <label className="flex items-center gap-2 cursor-pointer">
                                        <input 
                                            type="checkbox" 
                                            className="w-3 h-3 text-brand-600 rounded border-gray-300 focus:ring-brand-500"
                                            checked={inputs.dryingTimeSameAsPrintTime}
                                            onChange={(e) => handleInputChange('dryingTimeSameAsPrintTime', e.target.checked)}
                                        />
                                        <span className="text-[10px] font-bold text-brand-600">Sync with Print Time</span>
                                     </label>
                                   </div>
                                   <div className="flex gap-2">
                                     <InputGroup 
                                        label="" 
                                        type="number" 
                                        suffix="hrs" 
                                        className={clsx("mb-0", inputs.dryingTimeSameAsPrintTime && "opacity-50 pointer-events-none bg-gray-100")}
                                        value={inputs.dryingTimeSameAsPrintTime ? inputs.timeHours : inputs.dryingHours} 
                                        onChange={(e) => handleInputChange('dryingHours', e.target.value)} 
                                        placeholder="0"
                                     />
                                     <InputGroup 
                                        label="" 
                                        type="number" 
                                        suffix="min" 
                                        className={clsx("mb-0", inputs.dryingTimeSameAsPrintTime && "opacity-50 pointer-events-none bg-gray-100")}
                                        value={inputs.dryingTimeSameAsPrintTime ? inputs.timeMinutes : inputs.dryingMinutes} 
                                        onChange={(e) => handleInputChange('dryingMinutes', e.target.value)} 
                                        placeholder="0"
                                     />
                                   </div>
                                </div>

                                {/* Extras */}
                                <div className="md:col-span-2 lg:col-span-4 bg-gray-50 rounded-lg p-3 mt-2 border border-gray-100">
                                    <div className="flex justify-between items-center mb-2">
                                        <span className="text-[10px] font-bold text-gray-500 uppercase tracking-wider">Hardware & Extras</span>
                                        <button onClick={addExtra} className="text-[10px] text-brand-600 font-bold hover:underline bg-brand-50 px-2 py-0.5 rounded border border-brand-100">+ Add Item</button>
                                    </div>
                                    <div className="space-y-2">
                                        {inputs.extras.map(extra => (
                                            <div key={extra.id} className="flex gap-2">
                                                <input className="flex-1 text-sm border-gray-300 rounded px-2 py-1" value={extra.name} onChange={(e) => updateExtra(extra.id, 'name', e.target.value)} placeholder="Item name" />
                                                <input className="w-24 text-sm border-gray-300 rounded px-2 py-1" type="number" value={extra.price} onChange={(e) => updateExtra(extra.id, 'price', e.target.value)} placeholder="Price" />
                                                <button onClick={() => removeExtra(extra.id)} className="text-gray-400 hover:text-red-500"><Trash2 size={16}/></button>
                                            </div>
                                        ))}
                                        {inputs.extras.length === 0 && <p className="text-xs text-gray-400 italic">No extras added</p>}
                                    </div>
                                </div>
                            </div>
                        </section>

                        {/* Section 2: Factory Overhead */}
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="px-5 py-3 border-b border-gray-100 bg-gray-50/80 flex items-center gap-2">
                                <Zap size={16} className="text-gray-400" />
                                <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">02 // Factory Overhead</h2>
                            </div>
                            <div className="p-5 grid grid-cols-2 md:grid-cols-4 lg:grid-cols-4 gap-4">
                                <InputGroup label="Machine Cost" prefix="₱" value={inputs.machineCost} onChange={(e) => handleInputChange('machineCost', e.target.value)} />
                                <InputGroup label="Lifespan" suffix="hrs" value={inputs.lifespanHours} onChange={(e) => handleInputChange('lifespanHours', e.target.value)} />
                                <InputGroup label="Power Draw" suffix="W" value={inputs.powerWatts} onChange={(e) => handleInputChange('powerWatts', e.target.value)} />
                                <InputGroup 
                                    label="Dryer Power" 
                                    suffix="W" 
                                    value={inputs.dryerPowerWatts} 
                                    onChange={(e) => handleInputChange('dryerPowerWatts', e.target.value)}
                                    className="bg-orange-50/30 border-orange-100 focus:border-orange-500"
                                />
                                <InputGroup label="Elec. Rate" prefix="₱" suffix="/kWh" value={inputs.elecRate} onChange={(e) => handleInputChange('elecRate', e.target.value)} />
                                <InputGroup label="Labor Rate" prefix="₱" suffix="/hr" value={inputs.laborRate} onChange={(e) => handleInputChange('laborRate', e.target.value)} />
                                <InputGroup label="Prep Time" suffix="min" value={inputs.laborMins} onChange={(e) => handleInputChange('laborMins', e.target.value)} />
                            </div>
                        </section>

                        {/* Section 3: Commercial */}
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
                            <div className="px-5 py-3 border-b border-gray-100 bg-gray-50/80 flex items-center gap-2">
                                <TrendingUp size={16} className="text-gray-400" />
                                <h2 className="text-sm font-bold text-gray-700 uppercase tracking-wider">03 // Commercial</h2>
                            </div>
                            <div className="p-5 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
                                <InputGroup label="Fail Margin" suffix="%" value={inputs.failMargin} onChange={(e) => handleInputChange('failMargin', e.target.value)} />
                                <InputGroup label="Platform Fee" suffix="%" value={inputs.platformFee} onChange={(e) => handleInputChange('platformFee', e.target.value)} />
                                <InputGroup label="Tax Rate" suffix="%" value={inputs.taxRate} onChange={(e) => handleInputChange('taxRate', e.target.value)} />
                                <InputGroup label="Packaging" prefix="₱" value={inputs.packagingCost} onChange={(e) => handleInputChange('packagingCost', e.target.value)} />
                                <InputGroup label="Shipping" prefix="₱" value={inputs.shippingCost} onChange={(e) => handleInputChange('shippingCost', e.target.value)} />
                                <div className="relative">
                                    <InputGroup className="border-brand-300 bg-green-50 focus:ring-brand-500 font-bold text-brand-700" label="Markup Goal" suffix="%" value={inputs.markup} onChange={(e) => handleInputChange('markup', e.target.value)} />
                                </div>
                            </div>
                        </section>
                    </div>

                    {/* RIGHT COLUMN - HUD */}
                    <div className="xl:col-span-4 space-y-6">
                        <div className="sticky top-6">
                            <div className="bg-slate-900 text-white rounded-2xl shadow-2xl overflow-hidden border border-slate-800 ring-1 ring-white/10">

                                {/* HUD Header & Toggle */}
                                <div className="p-5 pb-0">
                                    <div className="flex items-center justify-between mb-4">
                                        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                                            <div className="w-2 h-2 bg-brand-500 rounded-full animate-pulse"></div>
                                            Live Pricing
                                        </span>
                                        <div className="flex bg-slate-800 p-1 rounded-lg border border-slate-700">
                                            <button 
                                                onClick={() => setViewMode('unit')}
                                                className={clsx("px-3 py-1 text-[10px] font-bold rounded-md transition-all uppercase tracking-wide", viewMode === 'unit' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                            >
                                                Per Unit
                                            </button>
                                            <button 
                                                onClick={() => setViewMode('batch')}
                                                className={clsx("px-3 py-1 text-[10px] font-bold rounded-md transition-all uppercase tracking-wide", viewMode === 'batch' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                            >
                                                Total Batch
                                            </button>
                                        </div>
                                    </div>

                                    {/* Chart Area */}
                                    <div className="flex justify-center py-2 h-40">
                                    <SummaryChart data={activeResult} currency={currency} />
                                    </div>
                                </div>

                                {/* Breakdown List */}
                                <div className="px-6 py-4 space-y-2.5">
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-blue-500"></span> Material
                                        </div>
                                        <span>{currency(activeResult?.material)}</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-purple-500"></span> Labor
                                        </div>
                                        <span>{currency(activeResult?.labor)}</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-yellow-500"></span> Energy/Machine
                                        </div>
                                        <span>{currency((activeResult?.energy || 0) + (activeResult?.depreciation || 0))}</span>
                                    </div>
                                    <div className="flex justify-between text-xs text-slate-400">
                                        <div className="flex items-center gap-2">
                                            <span className="w-2 h-2 rounded-full bg-slate-500"></span> Risk/Extras
                                        </div>
                                        <span>{currency((activeResult?.failureRisk || 0) + (activeResult?.extras || 0))}</span>
                                    </div>

                                    <div className="border-t border-slate-800 my-3 pt-3">
                                        <div className="flex justify-between items-center text-white font-medium text-sm">
                                            <span>Production Cost</span>
                                            <span>{currency(activeResult?.productionCost)}</span>
                                        </div>

                                        <div className="space-y-1 mt-2 pl-3 border-l-2 border-slate-800/50">
                                            <div className="flex justify-between text-[10px] text-slate-500">
                                                <span>+ Packaging</span>
                                                <span>{currency(activeResult?.packaging)}</span>
                                            </div>
                                            <div className="flex justify-between text-[10px] text-slate-500">
                                                <span>+ Tax</span>
                                                <span>{currency(activeResult?.tax)}</span>
                                            </div>
                                            <div className="flex justify-between text-[10px] text-slate-500">
                                                <span>+ Shipping</span>
                                                <span>{currency(activeResult?.shipping)}</span>
                                            </div>
                                            <div className="flex justify-between text-[10px] text-red-400/80">
                                                <span>+ Platform Fee</span>
                                                <span>{currency(activeResult?.platformFeeAmount)}</span>
                                            </div>
                                        </div>
                                    </div>

                                    <div className="flex justify-between items-center pt-1">
                                         <div className="text-slate-300 font-bold text-sm">
                                            Cost Basis
                                         </div>
                                         <button 
                                            onClick={() => setShowMathModal(true)}
                                            className="text-[10px] text-brand-400 hover:text-brand-300 hover:underline flex items-center gap-1"
                                         >
                                            <Calculator size={10} /> View Math
                                         </button>
                                    </div>
                                    <div className="text-right text-slate-300 font-bold text-sm">
                                        {currency(activeResult?.totalCostBasis)}
                                    </div>
                                </div>

                                {/* Footer Actions */}
                                <div className="bg-slate-800/80 p-5 border-t border-slate-700 backdrop-blur-sm">
                                    <div className="text-center mb-5">
                                        <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest mb-1">Recommended Price</p>
                                        <div className="text-3xl font-black text-white tracking-tight">
                                            {currency(activeResult?.finalPrice)}
                                        </div>
                                        <div className="text-brand-500 font-bold text-xs mt-1">
                                            {currency(activeResult?.profit)} Profit
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-3">
                                        <button 
                                            onClick={handleSave}
                                            disabled={isSaving}
                                            className="col-span-2 bg-brand-600 hover:bg-brand-500 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 transition-all shadow-lg shadow-brand-900/20 disabled:opacity-50 text-sm"
                                        >
                                            {isSaving ? <RefreshCw className="animate-spin" size={16} /> : <Save size={16} />}
                                            Save Job
                                        </button>
                                        <button 
                                            onClick={() => {
                                                const text = `Quote: ${inputs.jobName}\nPrice: ${currency(activeResult?.finalPrice)}`;
                                                navigator.clipboard.writeText(text);
                                                alert('Copied!');
                                            }}
                                            className="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs"
                                        >
                                            <Copy size={14} /> Copy
                                        </button>
                                         <button 
                                            onClick={() => setShowDashboard(true)}
                                            className="bg-slate-700 hover:bg-slate-600 text-white font-medium py-2.5 rounded-lg flex items-center justify-center gap-2 transition-all text-xs"
                                        >
                                            <LayoutDashboard size={14} /> Dash
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>

                </div>
            </div>
        </div>
      </div>
    </div>
  );
}

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { CalculatorInputs, CalculatedResults, HistoryItem, ExtraCost, CapitalItem } from './types';
import { DEFAULT_INPUTS } from './constants';
import { calculateCosts } from './services/calculatorService';
import { parseGCode } from './services/gcodeService';
import { saveJob, getJobs, deleteJob, saveCapitalItem, getCapitalItems, deleteCapitalItem } from './services/firebase';
import { loadSettings, saveSettings, mergeWithDefaults } from './services/settingsService';
import { InputGroup } from './components/InputGroup';
import { SummaryChart } from './components/SummaryChart';
import { HistoryPanel } from './components/HistoryPanel';
import { DashboardModal } from './components/DashboardModal';
import { MathModal } from './components/MathModal';
import { 
  Upload, Printer, Zap, DollarSign, Package, TrendingUp, 
  Save, Copy, RefreshCw, Box, Layers, Trash2, LayoutDashboard,
  ChevronLeft, ChevronRight, History, Calculator, Link
} from 'lucide-react';
import clsx from 'clsx';

function App() {
  // Initialize state with stored settings + defaults
  const [inputs, setInputs] = useState<CalculatorInputs>(() => {
    const saved = loadSettings();
    return mergeWithDefaults(saved);
  });

  // Initialize calculation based on that state
  const [results, setResults] = useState<CalculatedResults>(() => calculateCosts(inputs));

  const [viewMode, setViewMode] = useState<'unit' | 'batch'>('unit');
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [capitalHistory, setCapitalHistory] = useState<CapitalItem[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);
  const [showMathModal, setShowMathModal] = useState(false);

  // Sidebar State - Persisted
  const [isSidebarOpen, setIsSidebarOpen] = useState(() => {
    if (typeof window !== 'undefined') {
        const saved = localStorage.getItem('bambuCalc_Sidebar');
        return saved !== null ? JSON.parse(saved) : true;
    }
    return true;
  });

  // --- Sidebar Persistence ---
  useEffect(() => {
      localStorage.setItem('bambuCalc_Sidebar', JSON.stringify(isSidebarOpen));
  }, [isSidebarOpen]);

  // --- Calculations ---
  useEffect(() => {
    const res = calculateCosts(inputs);
    setResults(res);
  }, [inputs]);

  // --- Auto-Save Settings ---
  useEffect(() => {
    saveSettings(inputs);
  }, [
    inputs.materialCost,
    inputs.machineCost,
    inputs.lifespanHours,
    inputs.powerWatts,
    inputs.dryerPowerWatts, 
    inputs.elecRate,
    inputs.laborRate,
    inputs.laborMins,
    inputs.failMargin,
    inputs.platformFee,
    inputs.taxRate,
    inputs.packagingCost,
    inputs.shippingCost,
    inputs.markup
  ]);

  // --- Load Data ---
  useEffect(() => {
    getJobs().then(setHistory);
    getCapitalItems().then(setCapitalHistory);
  }, []);

  // --- Handlers ---
  const handleInputChange = (field: keyof CalculatorInputs, value: string | number | boolean) => {
    setInputs(prev => ({
      ...prev,
      [field]: value
    }));
  };

  const addExtra = () => {
    const newExtra: ExtraCost = {
      id: Date.now().toString(),
      name: 'New Item',
      price: 0
    };
    setInputs(prev => ({ ...prev, extras: [...prev.extras, newExtra] }));
  };

  const updateExtra = (id: string, field: 'name' | 'price', val: string) => {
    setInputs(prev => ({
      ...prev,
      extras: prev.extras.map(ex => 
        ex.id === id ? { ...ex, [field]: val } : ex
      )
    }));
  };

  const removeExtra = (id: string) => {
    setInputs(prev => ({ ...prev, extras: prev.extras.filter(ex => ex.id !== id) }));
  };

  // --- Drag & Drop ---
  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  }, []);

  const handleFile = (file: File) => {
    const reader = new FileReader();
    reader.onload = (e) => {
        const text = e.target?.result as string;
        const parsed = parseGCode(text);
        if (parsed.found) {
            setInputs(prev => ({
                ...prev,
                materialGrams: parsed.grams > 0 ? parsed.grams : prev.materialGrams,
                timeHours: parsed.hours,
                timeMinutes: parsed.minutes
            }));
            alert(`Parsed: ${parsed.grams}g, ${parsed.hours}h ${parsed.minutes}m`);
        } else {
            alert('Could not find specific time/weight data in this file. Try a Bambu or Prusa G-Code file.');
        }
    };
    reader.readAsText(file);
  };

  // --- Job Persistence ---
  const handleSave = async () => {
    setIsSaving(true);
    const newItem = {
        date: new Date().toLocaleDateString(),
        name: inputs.jobName,
        inputs: inputs,
        finalPrice: results.unit.finalPrice * (typeof inputs.batchQty === 'number' ? inputs.batchQty : parseFloat(inputs.batchQty as string) || 1)
    };

    await saveJob(newItem);
    const updated = await getJobs();
    setHistory(updated);
    setIsSaving(false);
  };

  const handleDeleteJob = async (id: string) => {
      await deleteJob(id);
      const updated = await getJobs();
      setHistory(updated);
  }

  // --- Capital Persistence ---
  const handleAddCapital = async (item: Omit<CapitalItem, 'id'>) => {
    await saveCapitalItem(item);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleDeleteCapital = async (id: string) => {
    await deleteCapitalItem(id);
    const updated = await getCapitalItems();
    setCapitalHistory(updated);
  };

  const handleLoad = (item: HistoryItem) => {
      setInputs(item.inputs);
      window.scrollTo({ top: 0, behavior: 'smooth' });
      setShowDashboard(false); // Close dashboard if open when loading
  };

  // --- Display Helpers ---
  const activeResult = viewMode === 'unit' ? results.unit : results.batch;
  const currency = (val: number | undefined) => `₱${(val || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">

      <DashboardModal 
        isOpen={showDashboard} 
        onClose={() => setShowDashboard(false)} 
        history={history} 
        capitalHistory={capitalHistory}
        onDeleteJob={handleDeleteJob}
        onAddCapital={handleAddCapital}
        onDeleteCapital={handleDeleteCapital}
        currency={currency}
      />

      <MathModal 
        isOpen={showMathModal}
        onClose={() => setShowMathModal(false)}
        inputs={inputs}
        results={results}
        currency={currency}
      />

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm flex-none">
        <div className="max-w-[1920px] mx-auto px-4 sm:px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-4">
             {/* Header Toggle Removed */}
             <div className="flex items-center gap-2">
                <div className="bg-brand-600 text-white p-1.5 rounded-lg">
                    <Printer size={20} />
                </div>
                <h1 className="text-lg font-bold text-gray-900 tracking-tight hidden sm:block">3D Print <span className="text-brand-600">Command</span></h1>
             </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
                onClick={() => setShowDashboard(true)}
                className="text-sm font-medium text-gray-600 hover:text-brand-600 hover:bg-gray-100 px-3 py-2 rounded-lg transition-colors flex items-center gap-2"
            >
                <LayoutDashboard size={18} /> <span className="hidden sm:inline">Dashboard</span>
            </button>
            <button 
                onClick={() => setInputs(DEFAULT_INPUTS)} 
                className="text-xs font-bold text-red-500 hover:bg-red-50 px-3 py-2 rounded-lg transition-colors border border-red-100"
            >
                Reset
            </button>
          </div>
        </div>
      </header>

      {/* Main Layout Area */}
      <div className="flex-1 flex overflow-hidden relative">

        {/* Toggle Button - Floating */}
        <button
            onClick={() => setIsSidebarOpen(!isSidebarOpen)}
            className={clsx(
                "absolute top-4 z-50 bg-white border border-gray-200 shadow-md h-8 w-6 rounded-r-lg flex items-center justify-center text-gray-400 hover:text-brand-600 transition-all duration-300 cursor-pointer",
                isSidebarOpen ? "left-72 border-l-0" : "left-0 border-l-0"
            )}
            title={isSidebarOpen ? "Collapse History" : "Expand History"}
        >
            {isSidebarOpen ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
        </button>

        {/* Sidebar */}
        <div 
            className={clsx(
                "bg-white border-r border-gray-200 flex flex-col transition-all duration-300 overflow-hidden relative z-30",
                isSidebarOpen ? "w-72 translate-x-0" : "w-0 -translate-x-full opacity-0"
            )}
        >
            <div className="p-4 bg-gray-50 border-b border-gray-100 flex items-center justify-between">
                <h3 className="font-bold text-gray-700 uppercase tracking-wider text-xs flex items-center gap-2">
                    <History size={14} /> Recent Jobs
                </h3>
                <span className="text-[10px] bg-white border border-gray-200 px-2 rounded-full text-gray-500">{history.length}</span>
            </div>
            <div className="flex-1 overflow-y-auto py-4">
                <HistoryPanel items={history} onLoad={handleLoad} onDelete={() => {}} />
            </div>
            <div className="p-4 border-t border-gray-200 bg-gray-50">
                <button onClick={() => setShowDashboard(true)} className="w-full py-2 text-xs font-bold text-brand-600 bg-white border border-brand-200 rounded-lg hover:bg-brand-50 transition-colors">
                    View Full History
                </button>
            </div>
        </div>

        {/* Scrollable Content */}
        <div className="flex-1 overflow-y-auto">
            <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-8">

                <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">

                    {/* LEFT COLUMN - INPUTS */}
                    <div className="xl:col-span-8 space-y-6">

                        {/* Drop Zone */}
                        <div 
                            onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                            onClick={() => document.getElementById('fileUpload')?.click()}
                            className={clsx(
                                "border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer group",
                                dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 hover:bg-white bg-gray-50/50"
                            )}
                        >
                            <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt" />
                            <div className="flex items-center justify-center gap-3">
                                <div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center">
                                    <Upload size={16} />
                                </div>
