                                            >
                                                Per Unit
                                            </button>
                                            <button 
                                                onClick={() => setViewMode('batch')}
                                                className={clsx("px-3 py-1 text-[10px] font-bold rounded-md transition-all uppercase tracking-wide", viewMode === 'batch' ? "bg-brand-600 text-white shadow-lg" : "text-slate-400 hover:text-white")}
                                            >
                                                Total Batch
