export default App;

import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem } from '../types';
import { calculateCosts } from '../services/calculatorService';
import { X, Trash2, Download, TrendingUp, DollarSign, Package, Plus, ShoppingCart, Wallet, CreditCard } from 'lucide-react';
import clsx from 'clsx';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => void;
  onDeleteCapital: (id: string) => void;
  currency: (val: number) => string;
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ 
  isOpen, onClose, history, capitalHistory, 
  onDeleteJob, onAddCapital, onDeleteCapital, currency 
}) => {
  const [activeTab, setActiveTab] = useState<'jobs' | 'capital'>('jobs');

  // New Capital Item State
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState('');
  const [newItemDate, setNewItemDate] = useState(new Date().toISOString().split('T')[0]);
  const [newItemCategory, setNewItemCategory] = useState<CapitalItem['category']>('Filament');
  const [newItemStore, setNewItemStore] = useState('');

  // Calculate aggregates - Hooks must run unconditionally
  const stats = useMemo(() => {
    let totalRev = 0;
    let totalProfit = 0;

    history.forEach(job => {
      const res = calculateCosts(job.inputs);
      const revenue = job.finalPrice || 0;
      const profit = res.batch.profit || 0;
      totalRev += revenue;
      totalProfit += profit;
    });

    const totalCapital = capitalHistory.reduce((acc, curr) => acc + (curr.price || 0), 0);
    const netPosition = totalProfit - totalCapital;
    const avgMargin = totalRev > 0 ? (totalProfit / totalRev) * 100 : 0;

    return { totalRev, totalProfit, avgMargin, totalCapital, netPosition };
  }, [history, capitalHistory]);

  // Conditional return must happen AFTER all hooks
  if (!isOpen) return null;

  const handleAddCapital = () => {
    if (!newItemName || !newItemPrice) return;
    onAddCapital({
      name: newItemName,
      price: parseFloat(newItemPrice),
      date: newItemDate,
      category: newItemCategory,
      store: newItemStore
    });
    // Reset form
    setNewItemName('');
    setNewItemPrice('');
    setNewItemStore('');
  };

  const downloadCSV = (headers: string[], rows: string[], filename: string) => {
    const csvContent = "data:text/csv;charset=utf-8," + [headers.join(','), ...rows].join('\n');
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", filename);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const exportCSV = () => {
    if (activeTab === 'jobs') {
      const headers = ['Date', 'Job Name', 'Qty', 'Material Cost', 'Hours', 'Total Price', 'Est. Profit'];
      const rows = history.map(job => {
        const res = calculateCosts(job.inputs);
        return [
          job.date, `"${job.name}"`, job.inputs.batchQty, job.inputs.materialCost, 
          job.inputs.timeHours, job.finalPrice.toFixed(2), res.batch.profit.toFixed(2)
        ].join(',');
      });
      downloadCSV(headers, rows, 'print_jobs_export.csv');
    } else {
      const headers = ['Date', 'Item Name', 'Category', 'Store', 'Price'];
      const rows = capitalHistory.map(item => {
        return [
          item.date, `"${item.name}"`, item.category, `"${item.store || ''}"`, item.price.toFixed(2)
        ].join(',');
      });
      downloadCSV(headers, rows, 'capital_expenses_export.csv');
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-6xl max-h-[95vh] overflow-hidden flex flex-col shadow-2xl">

        {/* Header */}
        <div className="flex justify-between items-center px-6 py-4 border-b border-gray-100 bg-white z-20">
          <div>
            <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
              Command Dashboard
              <span className="text-xs font-normal text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">Beta</span>
            </h2>
          </div>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full transition-colors">
            <X size={24} className="text-gray-500" />
          </button>
        </div>

        {/* Stats Overview - Always Visible */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-6 bg-gray-50 border-b border-gray-100">
            <StatsCard 
              icon={<DollarSign size={20} />} 
              label="Total Revenue" 
              value={currency(stats.totalRev)} 
              color="text-blue-600" bg="bg-blue-50" 
            />
             <StatsCard 
              icon={<TrendingUp size={20} />} 
              label="Total Profit" 
              value={currency(stats.totalProfit)} 
              color="text-green-600" bg="bg-green-50" 
            />
             <StatsCard 
              icon={<ShoppingCart size={20} />} 
              label="Capital Expenses" 
              value={currency(stats.totalCapital)} 
              color="text-orange-600" bg="bg-orange-50" 
            />
            <div className={clsx("p-4 rounded-xl border shadow-sm flex items-center gap-3", 
              stats.netPosition >= 0 ? "bg-brand-50 border-brand-200" : "bg-red-50 border-red-200"
            )}>
                <div className={clsx("p-2 rounded-lg", stats.netPosition >= 0 ? "bg-brand-100 text-brand-700" : "bg-red-100 text-red-600")}>
                    <Wallet size={20} />
                </div>
                <div>
                    <p className={clsx("text-[10px] font-bold uppercase tracking-wider", stats.netPosition >= 0 ? "text-brand-800" : "text-red-800")}>Net Position</p>
                    <p className={clsx("text-xl font-extrabold", stats.netPosition >= 0 ? "text-brand-700" : "text-red-700")}>
                      {stats.netPosition < 0 ? '-' : '+'}{currency(Math.abs(stats.netPosition))}
                    </p>
                </div>
            </div>
        </div>

        {/* Tab Navigation */}
        <div className="px-6 border-b border-gray-100 flex gap-6">
          <TabButton active={activeTab === 'jobs'} onClick={() => setActiveTab('jobs')} label="Job History" />
          <TabButton active={activeTab === 'capital'} onClick={() => setActiveTab('capital')} label="Inventory & Capital" />
          <div className="ml-auto py-3">
             <button onClick={exportCSV} className="text-xs font-bold text-gray-500 hover:text-brand-600 flex items-center gap-1">
                <Download size={14} /> Export CSV
             </button>
          </div>
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-auto bg-white relative">

          {activeTab === 'jobs' && (
             <table className="w-full text-left border-collapse">
                <thead className="bg-gray-50 sticky top-0 z-10 shadow-sm">
                    <tr>
                        <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Date</th>
                        <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase">Job Name</th>
                        <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-center">Qty</th>
                        <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Revenue</th>
                        <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Profit</th>
                        <th className="px-6 py-3 text-xs font-bold text-gray-500 uppercase text-right">Action</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                    {history.map((job) => {
                         const res = calculateCosts(job.inputs);
                         return (
                            <tr key={job.id} className="hover:bg-gray-50 transition-colors">
                                <td className="px-6 py-3 text-sm text-gray-500 whitespace-nowrap">{job.date}</td>
                                <td className="px-6 py-3 text-sm font-medium text-gray-900">{job.name || 'Untitled'}</td>
                                <td className="px-6 py-3 text-sm text-gray-600 text-center">{job.inputs.batchQty}</td>
                                <td className="px-6 py-3 text-sm text-gray-900 font-bold text-right">{currency(job.finalPrice)}</td>
                                <td className="px-6 py-3 text-sm text-green-600 font-medium text-right">{currency(res.batch.profit)}</td>
                                <td className="px-6 py-3 text-right">
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); if(confirm('Delete job?')) onDeleteJob(job.id); }}
                                        className="text-gray-400 hover:text-red-500 p-1 rounded transition-colors"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </td>
                            </tr>
                         );
                    })}
                    {history.length === 0 && <tr><td colSpan={6} className="text-center py-12 text-gray-400">No jobs recorded.</td></tr>}
                </tbody>
            </table>
          )}

          {activeTab === 'capital' && (
            <div>
              {/* Add New Expense Form */}
              <div className="bg-orange-50/50 p-4 border-b border-orange-100 flex flex-wrap gap-3 items-end">
                <div className="flex-1 min-w-[200px]">
                  <label className="block text-[10px] uppercase font-bold text-gray-500 mb-1">Item Name</label>
                  <input 
