import { initializeApp } from "firebase/app";
import { getFirestore, collection, addDoc, getDocs, deleteDoc, doc, query, orderBy, limit, Timestamp } from "firebase/firestore";
import { HistoryItem, CapitalItem } from "../types";

// --- ENVIRONMENT VARIABLE HELPER ---
// This ensures we can read keys whether you are using Vite (import.meta.env) 
// or Next.js/CRA (process.env).
const getEnv = (key: string) => {
  // 1. Try Vite
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env) {
      // @ts-ignore
      const val = import.meta.env[`VITE_${key}`] || import.meta.env[`NEXT_PUBLIC_${key}`];
      if (val) return val;
    }
  } catch (e) {}

  // 2. Try Standard/Next.js
  try {
    if (typeof process !== 'undefined' && process.env) {
      const val = process.env[`NEXT_PUBLIC_${key}`] || process.env[`REACT_APP_${key}`];
      if (val) return val;
    }
  } catch (e) {}

  return "";
};

// --- CONFIGURATION ---
const firebaseConfig = {
  apiKey: getEnv("FIREBASE_API_KEY"),
  authDomain: getEnv("FIREBASE_AUTH_DOMAIN"),
  projectId: getEnv("FIREBASE_PROJECT_ID"),
  storageBucket: getEnv("FIREBASE_STORAGE_BUCKET"),
  messagingSenderId: getEnv("FIREBASE_MESSAGING_SENDER_ID"),
  appId: getEnv("FIREBASE_APP_ID")
};

let db: any = null;
let useLocalStorage = true;

try {
  if (firebaseConfig.apiKey) {
    const app = initializeApp(firebaseConfig);
    db = getFirestore(app);
    useLocalStorage = false;
    console.log("✅ Firebase connected successfully to project:", firebaseConfig.projectId);
  } else {
    console.warn("⚠️ Firebase API Key not found in environment variables. Using LocalStorage fallback.");
    console.warn("   To fix: Add VITE_FIREBASE_API_KEY (or NEXT_PUBLIC_...) to your .env file or Vercel settings.");
  }
} catch (error) {
  console.error("❌ Error initializing Firebase, falling back to LocalStorage", error);
  useLocalStorage = true;
}

const JOBS_COLLECTION = "print_jobs";
const JOBS_STORAGE_KEY = "bambuCalc_History";

const CAPITAL_COLLECTION = "capital_expenses";
const CAPITAL_STORAGE_KEY = "bambuCalc_Capital";

// --- JOBS ---

export const saveJob = async (item: Omit<HistoryItem, 'id'>): Promise<HistoryItem> => {
  const finalItem: HistoryItem = {
    ...item,
    id: Date.now().toString(),
  };

  if (useLocalStorage) {
    const existing = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
    existing.unshift(finalItem);
    if (existing.length > 50) existing.pop();
    localStorage.setItem(JOBS_STORAGE_KEY, JSON.stringify(existing));
    return finalItem;
  } else {
    try {
      const docRef = await addDoc(collection(db, JOBS_COLLECTION), {
        ...item,
        createdAt: Timestamp.now()
      });
      return { ...item, id: docRef.id };
    } catch (e) {
      console.error("Firebase save failed:", e);
      alert("Failed to save to Cloud. Check console for permission errors.");
      return saveJobLocal(finalItem);
    }
  }
};

const saveJobLocal = (item: HistoryItem): HistoryItem => {
    const existing = JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
    existing.unshift(item);
    localStorage.setItem(JOBS_STORAGE_KEY, JSON.stringify(existing));
    return item;
}

export const getJobs = async (): Promise<HistoryItem[]> => {
  if (useLocalStorage) {
    return JSON.parse(localStorage.getItem(JOBS_STORAGE_KEY) || "[]");
  } else {
    try {
      const q = query(collection(db, JOBS_COLLECTION), orderBy("createdAt", "desc"), limit(50));
