  if (useLocalStorage) return JSON.parse(localStorage.getItem(`local_${colName}`) || "[]");
  try {
    const q = query(collection(db, colName), orderBy("createdAt", "desc"), limit(100));
    const snap = await getDocs(q);
    return snap.docs.map(d => ({ id: d.id, ...d.data() })) as T[];
  } catch (e) {
    return JSON.parse(localStorage.getItem(`local_${colName}`) || "[]");
  }
};

// Generic Saver
const saveItem = async <T>(colName: string, item: any, id?: string): Promise<any> => {
  const isUpdate = !!id;
  const now = Timestamp.now();
  const data = { 
    ...item, 
    updatedAt: now,
    createdAt: isUpdate ? (item.createdAt || now) : now 
  };

  if (useLocalStorage) {
    const list = JSON.parse(localStorage.getItem(`local_${colName}`) || "[]");
    if (isUpdate) {
      const idx = list.findIndex((i: any) => i.id === id);
      if (idx > -1) list[idx] = { ...data, id };
    } else {
      const newItem = { ...data, id: Date.now().toString() };
      list.unshift(newItem);
      return newItem;
    }
    localStorage.setItem(`local_${colName}`, JSON.stringify(list));
    return { ...data, id };
  }

  try {
    if (isUpdate) {
      await updateDoc(doc(db, colName, id), data);
      return { ...data, id };
    } else {
      const docRef = await addDoc(collection(db, colName), data);
      return { ...data, id: docRef.id };
