import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem, Product, Sale } from '../types';
import { calculateCosts } from '../services/calculatorService';
import { X, Trash2, Download, TrendingUp, DollarSign, Package, Plus, ShoppingCart, Wallet, Tags, ShoppingBag } from 'lucide-react';
import clsx from 'clsx';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  products: Product[];
  sales: Sale[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => void;
  onDeleteCapital: (id: string) => void;
  onAddProduct: (item: Omit<Product, 'id'>) => void;
  onDeleteProduct: (id: string) => void;
  onAddSale: (item: Omit<Sale, 'id'>) => void;
  onDeleteSale: (id: string) => void;
  currency: (val: number) => string;
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ 
  isOpen, onClose, history, capitalHistory, products, sales,
  onDeleteJob, onAddCapital, onDeleteCapital, 
  onAddProduct, onDeleteProduct, onAddSale, onDeleteSale, currency 
}) => {
  const [activeTab, setActiveTab] = useState<'jobs' | 'products' | 'sales' | 'capital'>('jobs');

  // Forms state
  const [newProd, setNewProd] = useState({ name: '', cost: '', price: '' });
  const [newSale, setNewSale] = useState({ itemId: '', qty: '1', type: 'product' as 'product' | 'job' });

  const stats = useMemo(() => {
    const totalJobRev = history.reduce((acc, j) => acc + (j.finalPrice || 0), 0);
    const totalSalesRev = sales.reduce((acc, s) => acc + (s.totalPrice || 0), 0);
    const totalSalesProfit = sales.reduce((acc, s) => acc + (s.totalProfit || 0), 0);
    const totalCapital = capitalHistory.reduce((acc, c) => acc + (c.price || 0), 0);

    // Estimate job profit (actual might differ, using calculated at time of job)
    const totalJobProfit = history.reduce((acc, j) => acc + calculateCosts(j.inputs).batch.profit, 0);

    return {
      revenue: totalJobRev + totalSalesRev,
      profit: totalJobProfit + totalSalesProfit,
      expenses: totalCapital,
      net: (totalJobProfit + totalSalesProfit) - totalCapital
    };
  }, [history, sales, capitalHistory]);

  if (!isOpen) return null;

  const handleAddProduct = () => {
    if (!newProd.name || !newProd.price) return;
    const cost = parseFloat(newProd.cost) || 0;
    const price = parseFloat(newProd.price) || 0;
    onAddProduct({
      name: newProd.name,
      unitCost: cost,
      unitPrice: price,
      profit: price - cost,
      createdAt: new Date()
    });
    setNewProd({ name: '', cost: '', price: '' });
  };

  const handleAddSale = () => {
    if (!newSale.itemId) return;
    const qty = parseInt(newSale.qty);
    let name = '', price = 0, profit = 0;

    if (newSale.type === 'product') {
        const p = products.find(x => x.id === newSale.itemId);
        if (p) { name = p.name; price = p.unitPrice * qty; profit = p.profit * qty; }
    } else {
        const j = history.find(x => x.id === newSale.itemId);
        if (j) { 
            name = j.name; 
            price = j.finalPrice * qty; 
            profit = calculateCosts(j.inputs).batch.profit * qty; 
        }
    }

    onAddSale({
        itemId: newSale.itemId,
        itemName: name,
        itemType: newSale.type,
        qty,
        totalPrice: price,
        totalProfit: profit,
        date: new Date().toLocaleDateString(),
        createdAt: new Date()
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-6xl max-h-[95vh] overflow-hidden flex flex-col shadow-2xl">

        <div className="flex justify-between items-center px-6 py-4 border-b">
          <h2 className="text-xl font-bold flex items-center gap-2"><LayoutDashboard className="text-brand-600"/> Command Dashboard</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full"><X size={24} /></button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-6 bg-gray-50 border-b">
            <StatsCard label="Revenue" value={currency(stats.revenue)} color="text-blue-600" />
            <StatsCard label="Sales Profit" value={currency(stats.profit)} color="text-green-600" />
            <StatsCard label="CapEx" value={currency(stats.expenses)} color="text-orange-600" />
            <div className="bg-white p-4 rounded-xl border flex flex-col">
                <span className="text-[10px] font-bold text-gray-500 uppercase">Net Position</span>
                <span className={clsx("text-xl font-bold", stats.net >= 0 ? "text-brand-600" : "text-red-600")}>{currency(stats.net)}</span>
            </div>
        </div>

        <div className="px-6 border-b flex gap-6 overflow-x-auto">
          <TabBtn active={activeTab === 'jobs'} onClick={() => setActiveTab('jobs')} label="Jobs" icon={<Box size={14}/>} />
          <TabBtn active={activeTab === 'products'} onClick={() => setActiveTab('products')} label="Products" icon={<Tags size={14}/>} />
          <TabBtn active={activeTab === 'sales'} onClick={() => setActiveTab('sales')} label="Sales" icon={<ShoppingBag size={14}/>} />
          <TabBtn active={activeTab === 'capital'} onClick={() => setActiveTab('capital')} label="Expenses" icon={<DollarSign size={14}/>} />
        </div>

        <div className="flex-1 overflow-auto p-6">
          {activeTab === 'jobs' && (
             <table className="w-full text-left">
                <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-bold">
                    <tr><th className="px-4 py-3">Date</th><th className="px-4 py-3">Name</th><th className="px-4 py-3 text-right">Price</th><th className="px-4 py-3 text-right">Action</th></tr>
                </thead>
                <tbody className="divide-y text-sm">
                    {history.map(j => (
                        <tr key={j.id} className="hover:bg-gray-50">
                            <td className="px-4 py-3 text-gray-500">{j.date} {j.updatedAt && <span className="text-[8px] bg-blue-50 text-blue-500 px-1 rounded ml-1">Edited</span>}</td>
                            <td className="px-4 py-3 font-medium">{j.name}</td>
                            <td className="px-4 py-3 text-right font-bold text-brand-600">{currency(j.finalPrice)}</td>
                            <td className="px-4 py-3 text-right">
                                <button onClick={() => onDeleteJob(j.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                            </td>
                        </tr>
                    ))}
                </tbody>
             </table>
          )}

          {activeTab === 'products' && (
             <div className="space-y-6">
                <div className="bg-brand-50 p-4 rounded-xl border border-brand-100 flex gap-3 items-end">
                    <div className="flex-1"><label className="text-[10px] font-bold text-brand-700 uppercase">Name</label><input className="w-full text-sm p-2 rounded border" value={newProd.name} onChange={e => setNewProd({...newProd, name: e.target.value})} placeholder="Articulated Dragon"/></div>
                    <div className="w-32"><label className="text-[10px] font-bold text-brand-700 uppercase">Unit Cost</label><input type="number" className="w-full text-sm p-2 rounded border" value={newProd.cost} onChange={e => setNewProd({...newProd, cost: e.target.value})} placeholder="0.00"/></div>
                    <div className="w-32"><label className="text-[10px] font-bold text-brand-700 uppercase">Unit Price</label><input type="number" className="w-full text-sm p-2 rounded border" value={newProd.price} onChange={e => setNewProd({...newProd, price: e.target.value})} placeholder="0.00"/></div>
                    <button onClick={handleAddProduct} className="bg-brand-600 text-white px-4 py-2 rounded font-bold text-sm">Add Product</button>
                </div>
                <table className="w-full text-left">
                    <thead className="text-[10px] uppercase text-gray-400 font-bold"><tr><th className="px-4 py-2">Product</th><th className="px-4 py-2">Cost</th><th className="px-4 py-2">Price</th><th className="px-4 py-2 text-right">Profit</th><th className="px-4 py-2 text-right">Action</th></tr></thead>
                    <tbody className="divide-y text-sm">
                        {products.map(p => (
                            <tr key={p.id} className="hover:bg-gray-50">
                                <td className="px-4 py-3 font-medium">{p.name}</td>
                                <td className="px-4 py-3 text-gray-500">{currency(p.unitCost)}</td>
                                <td className="px-4 py-3 font-bold">{currency(p.unitPrice)}</td>
                                <td className="px-4 py-3 text-right text-green-600 font-bold">{currency(p.profit)}</td>
                                <td className="px-4 py-3 text-right"><button onClick={() => onDeleteProduct(p.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
          )}

          {activeTab === 'sales' && (
            <div className="space-y-6">
                <div className="bg-green-50 p-4 rounded-xl border border-green-100 flex gap-3 items-end">
                    <div className="flex-1">
                        <label className="text-[10px] font-bold text-green-700 uppercase">Item</label>
                        <select className="w-full text-sm p-2 rounded border" value={newSale.itemId} onChange={e => {
                            const val = e.target.value;
                            const type = products.some(p => p.id === val) ? 'product' : 'job';
                            setNewSale({...newSale, itemId: val, type});
                        }}>
                            <option value="">Select Item...</option>
                            <optgroup label="Products">
                                {products.map(p => <option key={p.id} value={p.id}>{p.name} ({currency(p.unitPrice)})</option>)}
                            </optgroup>
                            <optgroup label="Custom Jobs">
                                {history.map(j => <option key={j.id} value={j.id}>{j.name} ({currency(j.finalPrice)})</option>)}
                            </optgroup>
                        </select>
                    </div>
                    <div className="w-24"><label className="text-[10px] font-bold text-green-700 uppercase">Qty</label><input type="number" className="w-full text-sm p-2 rounded border" value={newSale.qty} onChange={e => setNewSale({...newSale, qty: e.target.value})}/></div>
                    <button onClick={handleAddSale} className="bg-green-600 text-white px-4 py-2 rounded font-bold text-sm">Log Sale</button>
                </div>
                <table className="w-full text-left">
                    <thead className="text-[10px] uppercase text-gray-400 font-bold"><tr><th className="px-4 py-2">Date</th><th className="px-4 py-2">Item</th><th className="px-4 py-2">Qty</th><th className="px-4 py-2 text-right">Total</th><th className="px-4 py-2 text-right">Profit</th></tr></thead>
                    <tbody className="divide-y text-sm">
                        {sales.map(s => (
                            <tr key={s.id} className="hover:bg-gray-50">
                                <td className="px-4 py-3 text-gray-500">{s.date}</td>
                                <td className="px-4 py-3 font-medium">{s.itemName} <span className="text-[10px] bg-gray-100 px-1 rounded">{s.itemType}</span></td>
                                <td className="px-4 py-3">{s.qty}</td>
                                <td className="px-4 py-3 text-right font-bold">{currency(s.totalPrice)}</td>
                                <td className="px-4 py-3 text-right text-green-600 font-bold">{currency(s.totalProfit)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
          )}

          {activeTab === 'capital' && (
             <table className="w-full text-left">
                <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-bold"><tr><th className="px-4 py-3">Date</th><th className="px-4 py-3">Category</th><th className="px-4 py-3">Item</th><th className="px-4 py-3 text-right">Cost</th></tr></thead>
                <tbody className="divide-y text-sm">
                    {capitalHistory.map(c => (
                        <tr key={c.id}>
                            <td className="px-4 py-3 text-gray-500">{c.date}</td>
                            <td className="px-4 py-3"><span className="px-2 py-0.5 rounded text-[10px] font-bold bg-orange-50 text-orange-600">{c.category}</span></td>
                            <td className="px-4 py-3 font-medium">{c.name}</td>
                            <td className="px-4 py-3 text-right font-bold text-red-600">{currency(c.price)}</td>
                        </tr>
                    ))}
                </tbody>
             </table>
          )}
        </div>
      </div>
    </div>
  );
};

