const getEnv = (key: string, defaultValue: string = "") => {
  try {
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env) {
      // @ts-ignore
      const val = import.meta.env[`VITE_FIREBASE_${key}`] || import.meta.env[`NEXT_PUBLIC_FIREBASE_${key}`];
      if (val) return val;
    }
  } catch (e) {}
  try {
    if (typeof process !== 'undefined' && process.env) {
      const val = process.env[`NEXT_PUBLIC_FIREBASE_${key}`] || process.env[`REACT_APP_FIREBASE_${key}`];
      if (val) return val;
    }
  } catch (e) {}
  return defaultValue;
};

