  const currency = (val: number | undefined) => `₱${(val || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <DashboardModal 
        isOpen={showDashboard} 
        onClose={() => setShowDashboard(false)} 
        history={history} 
        capitalHistory={capitalHistory}
        products={products}
        sales={sales}
        onDeleteJob={async (id) => { await deleteJob(id); loadData(); }}
        onAddCapital={async (item) => { await saveCapitalItem(item); loadData(); }}
        onDeleteCapital={async (id) => { await deleteCapitalItem(id); loadData(); }}
        onAddProduct={async (p) => { await saveProduct(p); loadData(); }}
        onDeleteProduct={async (id) => { await deleteProduct(id); loadData(); }}
        onAddSale={async (s) => { await saveSale(s); loadData(); }}
        onDeleteSale={async (id) => { await deleteSale(id); loadData(); }}
        currency={currency}
      />

      <MathModal isOpen={showMathModal} onClose={() => setShowMathModal(false)} inputs={inputs} results={results} currency={currency} />

      <header className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm h-16 flex items-center justify-between px-4 sm:px-6">
          <div className="flex items-center gap-2">
            <div className="bg-brand-600 text-white p-1.5 rounded-lg"><Printer size={20} /></div>
            <h1 className="text-lg font-bold text-gray-900 tracking-tight hidden sm:block">3D Print <span className="text-brand-600">Command</span></h1>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setShowDashboard(true)} className="text-sm font-medium text-gray-600 hover:text-brand-600 px-3 py-2 rounded-lg flex items-center gap-2 hover:bg-gray-50"><LayoutDashboard size={18} /> Dash</button>
            <button onClick={resetForm} className="text-xs font-bold text-red-500 hover:bg-red-50 px-3 py-2 rounded-lg border border-red-100">Reset</button>
          </div>
      </header>

      <div className="flex-1 flex overflow-hidden relative">
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className={clsx("absolute top-4 z-50 bg-white border border-gray-200 shadow-md h-8 w-6 rounded-r-lg flex items-center justify-center text-gray-400 hover:text-brand-600 transition-all", isSidebarOpen ? "left-72" : "left-0")}><ChevronLeft size={14} className={clsx(!isSidebarOpen && "rotate-180")} /></button>
        <div className={clsx("bg-white border-r border-gray-200 flex flex-col transition-all overflow-hidden relative z-30", isSidebarOpen ? "w-72" : "w-0")}>
            <div className="p-4 bg-gray-50 border-b flex items-center justify-between"><h3 className="font-bold text-gray-700 uppercase tracking-wider text-xs flex items-center gap-2"><History size={14}/> Recent Jobs</h3></div>
            <div className="flex-1 overflow-y-auto py-4"><HistoryPanel items={history} onLoad={handleLoadJob} onDelete={() => {}} /></div>
        </div>

        <div className="flex-1 overflow-y-auto">
            <div className="max-w-[1600px] mx-auto px-4 py-8">
                <div className="grid grid-cols-1 xl:grid-cols-12 gap-8">
                    <div className="xl:col-span-8 space-y-6">

                        <div 
                            onDragEnter={handleDrag} onDragLeave={handleDrag} onDragOver={handleDrag} onDrop={handleDrop}
                            onClick={() => document.getElementById('fileUpload')?.click()}
                            className={clsx("border-2 border-dashed rounded-2xl p-6 text-center transition-all cursor-pointer group", dragActive ? "border-brand-500 bg-brand-50" : "border-gray-300 hover:border-brand-400 bg-gray-50/50")}
                        >
                            <input type="file" id="fileUpload" className="hidden" onChange={(e) => e.target.files && handleFile(e.target.files[0])} accept=".gcode,.txt" />
                            <div className="flex items-center justify-center gap-3"><div className="w-8 h-8 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center"><Upload size={16} /></div><div className="text-left"><h3 className="font-semibold text-gray-900 text-sm">Import G-Code</h3><p className="text-xs text-gray-500">Drag & drop or click</p></div></div>
                        </div>

                        {editingJobId && (
                            <div className="bg-amber-50 border border-amber-200 p-3 rounded-lg flex items-center justify-between">
                                <span className="text-sm font-medium text-amber-800 flex items-center gap-2"><Edit3 size={16}/> Editing Job: <strong>{inputs.jobName}</strong></span>
                                <button onClick={() => setEditingJobId(null)} className="text-xs text-amber-600 font-bold hover:underline">Cancel Edit</button>
                            </div>
                        )}
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm p-5 space-y-6">
                            <div className="flex items-center gap-2 border-b border-gray-100 pb-3"><Box size={16}/><h2 className="text-sm font-bold text-gray-700 uppercase">01 // Specifications</h2></div>
                            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                                <div className="md:col-span-2"><InputGroup label="Job Name" value={inputs.jobName} onChange={e => handleInputChange('jobName', e.target.value)} /></div>
                                <InputGroup label="Batch Qty" type="number" value={inputs.batchQty} onChange={e => handleInputChange('batchQty', e.target.value)} />
                                <InputGroup label="Filament (g)" type="number" value={inputs.materialGrams} onChange={e => handleInputChange('materialGrams', e.target.value)} />
                                <InputGroup label="Material Cost (1kg)" type="number" prefix="₱" value={inputs.materialCost} onChange={e => handleInputChange('materialCost', e.target.value)} />
                                <InputGroup label="Print Hours" type="number" value={inputs.timeHours} onChange={e => handleInputChange('timeHours', e.target.value)} />
                                <InputGroup label="Print Minutes" type="number" value={inputs.timeMinutes} onChange={e => handleInputChange('timeMinutes', e.target.value)} />
                                {/* Extras */}
                                <div className="md:col-span-2 lg:col-span-4 bg-gray-50 rounded-lg p-3 mt-2 border border-gray-100">
                                    <div className="flex justify-between items-center mb-2"><span className="text-[10px] font-bold text-gray-500 uppercase">Hardware & Extras</span><button onClick={addExtra} className="text-[10px] text-brand-600 font-bold hover:underline bg-brand-50 px-2 py-0.5 rounded border border-brand-100">+ Add</button></div>
                                    <div className="space-y-2">{inputs.extras.map(extra => (<div key={extra.id} className="flex gap-2"><input className="flex-1 text-sm border-gray-300 rounded px-2 py-1" value={extra.name} onChange={(e) => updateExtra(extra.id, 'name', e.target.value)} placeholder="Item" /><input className="w-24 text-sm border-gray-300 rounded px-2 py-1" type="number" value={extra.price} onChange={(e) => updateExtra(extra.id, 'price', e.target.value)} placeholder="Price" /><button onClick={() => removeExtra(extra.id)} className="text-gray-400 hover:text-red-500"><Trash2 size={16}/></button></div>))}</div>
                                </div>
                            </div>
                        </section>
                        <section className="bg-white rounded-xl border border-gray-200 shadow-sm p-5"><h2 className="text-sm font-bold text-gray-700 uppercase mb-4 flex items-center gap-2"><TrendingUp size={16}/> 02 // Commercial</h2>
                            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                                <InputGroup label="Fail Margin %" type="number" value={inputs.failMargin} onChange={e => handleInputChange('failMargin', e.target.value)} />
                                <InputGroup label="Platform Fee %" type="number" value={inputs.platformFee} onChange={e => handleInputChange('platformFee', e.target.value)} />
                                <InputGroup label="Markup %" type="number" value={inputs.markup} onChange={e => handleInputChange('markup', e.target.value)} />
                                <InputGroup label="Packaging" type="number" prefix="₱" value={inputs.packagingCost} onChange={e => handleInputChange('packagingCost', e.target.value)} />
                            </div>
                        </section>
                    </div>

                    <div className="xl:col-span-4">
                        <div className="sticky top-20 bg-slate-900 text-white rounded-2xl p-6 shadow-2xl">
                            <div className="flex items-center justify-between mb-4">
                                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Pricing HUD</span>
                                <div className="flex bg-slate-800 p-1 rounded-lg">
                                    <button onClick={() => setViewMode('unit')} className={clsx("px-3 py-1 text-[10px] rounded", viewMode === 'unit' ? "bg-brand-600" : "text-slate-400")}>Unit</button>
                                    <button onClick={() => setViewMode('batch')} className={clsx("px-3 py-1 text-[10px] rounded", viewMode === 'batch' ? "bg-brand-600" : "text-slate-400")}>Batch</button>
                                </div>
                            </div>
                            <div className="h-40 flex justify-center"><SummaryChart data={viewMode === 'unit' ? results.unit : results.batch} currency={currency} /></div>
                            <div className="mt-6 text-center">
                                <p className="text-slate-400 text-[10px] font-bold uppercase">Price Suggestion</p>
                                <div className="text-3xl font-black text-white">{currency(viewMode === 'unit' ? results.unit.finalPrice : results.batch.finalPrice)}</div>
                            </div>
                            <button 
                                onClick={handleSaveOrUpdate}
                                disabled={isSaving}
                                className="w-full mt-6 bg-brand-600 hover:bg-brand-500 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2"
                            >
                                {isSaving ? <RefreshCw className="animate-spin" size={16} /> : (editingJobId ? <Edit3 size={16}/> : <Save size={16} />)}
                                {editingJobId ? 'Update Job' : 'Save Job'}
                            </button>
                            <button onClick={() => setShowMathModal(true)} className="w-full mt-3 text-xs text-brand-400 hover:text-white flex items-center justify-center gap-2"><Calculator size={14}/> Show Math</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
}

export default App;

import React, { useMemo, useState } from 'react';
import { HistoryItem, CapitalItem, Product, Sale } from '../types';
import { calculateCosts } from '../services/calculatorService';
import { X, Trash2, Download, TrendingUp, DollarSign, Package, Plus, ShoppingCart, Wallet, Tags, ShoppingBag, LayoutDashboard, Box } from 'lucide-react';
import clsx from 'clsx';

interface DashboardModalProps {
  isOpen: boolean;
  onClose: () => void;
  history: HistoryItem[];
  capitalHistory: CapitalItem[];
  products: Product[];
  sales: Sale[];
  onDeleteJob: (id: string) => void;
  onAddCapital: (item: Omit<CapitalItem, 'id'>) => void;
  onDeleteCapital: (id: string) => void;
  onAddProduct: (item: Omit<Product, 'id'>) => void;
  onDeleteProduct: (id: string) => void;
  onAddSale: (item: Omit<Sale, 'id'>) => void;
  onDeleteSale: (id: string) => void;
  currency: (val: number) => string;
}

export const DashboardModal: React.FC<DashboardModalProps> = ({ 
  isOpen, onClose, history, capitalHistory, products, sales,
  onDeleteJob, onAddCapital, onDeleteCapital, 
  onAddProduct, onDeleteProduct, onAddSale, onDeleteSale, currency 
}) => {
  const [activeTab, setActiveTab] = useState<'jobs' | 'products' | 'sales' | 'capital'>('jobs');

  // Forms state
  const [newProd, setNewProd] = useState({ name: '', cost: '', price: '' });
  const [newSale, setNewSale] = useState({ itemId: '', qty: '1', type: 'product' as 'product' | 'job' });
  const [newCap, setNewCap] = useState({ name: '', price: '', category: 'Filament' as any, store: '' });

  const stats = useMemo(() => {
    // Revenue is mainly driven by Sales. We can optionally add 'Job History' as potential revenue, 
    // but users usually want 'Realized' revenue in a Sales tab.
    // To keep it simple and powerful:
    // Revenue = Total Sales
    // Profit = Total Sales Profit
    // Net = Profit - Expenses

    const totalSalesRev = sales.reduce((acc, s) => acc + (s.totalPrice || 0), 0);
    const totalSalesProfit = sales.reduce((acc, s) => acc + (s.totalProfit || 0), 0);
    const totalCapital = capitalHistory.reduce((acc, c) => acc + (c.price || 0), 0);

    return {
      revenue: totalSalesRev,
      profit: totalSalesProfit,
      expenses: totalCapital,
      net: totalSalesProfit - totalCapital
    };
  }, [sales, capitalHistory]);

  if (!isOpen) return null;

  const handleAddProduct = () => {
    if (!newProd.name || !newProd.price) return;
    const cost = parseFloat(newProd.cost) || 0;
    const price = parseFloat(newProd.price) || 0;
    onAddProduct({
      name: newProd.name,
      unitCost: cost,
      unitPrice: price,
      profit: price - cost,
      createdAt: new Date()
    });
    setNewProd({ name: '', cost: '', price: '' });
  };

  const handleAddSale = () => {
    if (!newSale.itemId) return;
    const qty = parseInt(newSale.qty) || 1;
    let name = '', price = 0, profit = 0;

    if (newSale.type === 'product') {
        const p = products.find(x => x.id === newSale.itemId);
        if (p) { name = p.name; price = p.unitPrice * qty; profit = p.profit * qty; }
    } else {
        const j = history.find(x => x.id === newSale.itemId);
        if (j) { 
            const costs = calculateCosts(j.inputs);
            name = j.name; 
            price = j.finalPrice * qty; // Job final price is usually per batch in the history if batch > 1? 
            // Actually history finalPrice is "total price" of that job entry.
            // If I sell 1 "Job", I am selling that whole entry? Or is the Job Entry a "Unit"?
            // Usually Job History stores a specific run.
            // Let's assume the user picks a job to represent a "SKU".
            // If the job history has batchQty=10 and price=1000.
            // And I sell "1" of this job, it means 1 unit or 1 run?
            // To be safe: We treat the Job Entry as a "Defined Product" where Price = `finalPrice / inputs.batchQty`.

            const unitPrice = j.finalPrice / (Number(j.inputs.batchQty)||1);
            const unitProfit = costs.batch.profit / (Number(j.inputs.batchQty)||1);

            price = unitPrice * qty;
            profit = unitProfit * qty;
        }
    }

    onAddSale({
        itemId: newSale.itemId,
        itemName: name,
        itemType: newSale.type,
        qty,
        totalPrice: price,
        totalProfit: profit,
        date: new Date().toLocaleDateString(),
        createdAt: new Date()
    });
    setNewSale({ itemId: '', qty: '1', type: 'product' });
  };

  const handleAddCapital = () => {
      if(!newCap.name || !newCap.price) return;
      onAddCapital({
          name: newCap.name,
          price: parseFloat(newCap.price),
          category: newCap.category,
          store: newCap.store,
          date: new Date().toLocaleDateString()
      });
      setNewCap({ name: '', price: '', category: 'Filament', store: '' });
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-white rounded-2xl w-full max-w-6xl max-h-[95vh] overflow-hidden flex flex-col shadow-2xl">

        <div className="flex justify-between items-center px-6 py-4 border-b">
          <h2 className="text-xl font-bold flex items-center gap-2"><LayoutDashboard className="text-brand-600"/> Command Dashboard</h2>
          <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full"><X size={24} /></button>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-6 bg-gray-50 border-b">
            <StatsCard label="Sales Revenue" value={currency(stats.revenue)} color="text-blue-600" />
            <StatsCard label="Sales Profit" value={currency(stats.profit)} color="text-green-600" />
            <StatsCard label="CapEx" value={currency(stats.expenses)} color="text-orange-600" />
            <div className="bg-white p-4 rounded-xl border flex flex-col">
                <span className="text-[10px] font-bold text-gray-500 uppercase">Net Position</span>
                <span className={clsx("text-xl font-bold", stats.net >= 0 ? "text-brand-600" : "text-red-600")}>{currency(stats.net)}</span>
            </div>
        </div>

        <div className="px-6 border-b flex gap-6 overflow-x-auto">
          <TabBtn active={activeTab === 'jobs'} onClick={() => setActiveTab('jobs')} label="Quote History" icon={<Box size={14}/>} />
          <TabBtn active={activeTab === 'products'} onClick={() => setActiveTab('products')} label="Products" icon={<Tags size={14}/>} />
          <TabBtn active={activeTab === 'sales'} onClick={() => setActiveTab('sales')} label="Sales" icon={<ShoppingBag size={14}/>} />
          <TabBtn active={activeTab === 'capital'} onClick={() => setActiveTab('capital')} label="Expenses" icon={<DollarSign size={14}/>} />
        </div>

        <div className="flex-1 overflow-auto p-6 bg-gray-50/50">
          {activeTab === 'jobs' && (
             <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
                <table className="w-full text-left">
                    <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-bold">
                        <tr><th className="px-4 py-3">Date</th><th className="px-4 py-3">Job Name</th><th className="px-4 py-3 text-right">Batch Price</th><th className="px-4 py-3 text-right">Action</th></tr>
                    </thead>
                    <tbody className="divide-y text-sm">
                        {history.map(j => (
                            <tr key={j.id} className="hover:bg-gray-50">
                                <td className="px-4 py-3 text-gray-500">{j.date} {j.updatedAt && <span className="text-[9px] bg-blue-100 text-blue-600 px-1 rounded ml-1">Edited</span>}</td>
                                <td className="px-4 py-3 font-medium">{j.name}</td>
                                <td className="px-4 py-3 text-right font-bold text-brand-600">{currency(j.finalPrice)}</td>
                                <td className="px-4 py-3 text-right">
                                    <button onClick={() => onDeleteJob(j.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
             </div>
          )}

          {activeTab === 'products' && (
             <div className="space-y-6">
                <div className="bg-white p-4 rounded-xl border border-brand-100 shadow-sm flex flex-wrap gap-3 items-end">
                    <div className="flex-1 min-w-[200px]"><label className="text-[10px] font-bold text-gray-500 uppercase">Product Name</label><input className="w-full text-sm p-2 rounded border focus:ring-brand-500" value={newProd.name} onChange={e => setNewProd({...newProd, name: e.target.value})} placeholder="e.g. Articulated Dragon"/></div>
                    <div className="w-32"><label className="text-[10px] font-bold text-gray-500 uppercase">Unit Cost</label><input type="number" className="w-full text-sm p-2 rounded border focus:ring-brand-500" value={newProd.cost} onChange={e => setNewProd({...newProd, cost: e.target.value})} placeholder="0.00"/></div>
                    <div className="w-32"><label className="text-[10px] font-bold text-gray-500 uppercase">Unit Price</label><input type="number" className="w-full text-sm p-2 rounded border focus:ring-brand-500" value={newProd.price} onChange={e => setNewProd({...newProd, price: e.target.value})} placeholder="0.00"/></div>
                    <button onClick={handleAddProduct} className="bg-brand-600 text-white px-4 py-2 rounded font-bold text-sm hover:bg-brand-700">Add Product</button>
                </div>
                <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-bold"><tr><th className="px-4 py-2">Product</th><th className="px-4 py-2">Cost</th><th className="px-4 py-2">Price</th><th className="px-4 py-2 text-right">Profit</th><th className="px-4 py-2 text-right">Action</th></tr></thead>
                        <tbody className="divide-y text-sm">
                            {products.map(p => (
                                <tr key={p.id} className="hover:bg-gray-50">
                                    <td className="px-4 py-3 font-medium">{p.name}</td>
                                    <td className="px-4 py-3 text-gray-500">{currency(p.unitCost)}</td>
                                    <td className="px-4 py-3 font-bold">{currency(p.unitPrice)}</td>
                                    <td className="px-4 py-3 text-right text-green-600 font-bold">{currency(p.profit)}</td>
                                    <td className="px-4 py-3 text-right"><button onClick={() => onDeleteProduct(p.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                                </tr>
                            ))}
                            {products.length === 0 && <tr><td colSpan={5} className="text-center py-8 text-gray-400">No products added.</td></tr>}
                        </tbody>
                    </table>
                </div>
             </div>
          )}

          {activeTab === 'sales' && (
            <div className="space-y-6">
                <div className="bg-white p-4 rounded-xl border border-green-100 shadow-sm flex flex-wrap gap-3 items-end">
                    <div className="flex-1 min-w-[200px]">
                        <label className="text-[10px] font-bold text-gray-500 uppercase">Item to Sell</label>
                        <select className="w-full text-sm p-2 rounded border focus:ring-green-500" value={newSale.itemId} onChange={e => {
                            const val = e.target.value;
                            const type = products.some(p => p.id === val) ? 'product' : 'job';
                            setNewSale({...newSale, itemId: val, type});
                        }}>
                            <option value="">Select Item...</option>
                            <optgroup label="Standard Products">
                                {products.map(p => <option key={p.id} value={p.id}>{p.name} ({currency(p.unitPrice)})</option>)}
                            </optgroup>
                            <optgroup label="Custom Job Quotes">
                                {history.map(j => <option key={j.id} value={j.id}>{j.name} (Quote: {currency(j.finalPrice)})</option>)}
                            </optgroup>
                        </select>
                    </div>
                    <div className="w-24"><label className="text-[10px] font-bold text-gray-500 uppercase">Qty</label><input type="number" className="w-full text-sm p-2 rounded border focus:ring-green-500" value={newSale.qty} onChange={e => setNewSale({...newSale, qty: e.target.value})}/></div>
                    <button onClick={handleAddSale} className="bg-green-600 text-white px-4 py-2 rounded font-bold text-sm hover:bg-green-700">Log Sale</button>
                </div>
                <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-bold"><tr><th className="px-4 py-2">Date</th><th className="px-4 py-2">Item</th><th className="px-4 py-2">Qty</th><th className="px-4 py-2 text-right">Total</th><th className="px-4 py-2 text-right">Profit</th><th className="px-4 py-2 text-right"></th></tr></thead>
                        <tbody className="divide-y text-sm">
                            {sales.map(s => (
                                <tr key={s.id} className="hover:bg-gray-50">
                                    <td className="px-4 py-3 text-gray-500">{s.date}</td>
                                    <td className="px-4 py-3 font-medium">{s.itemName} <span className="text-[9px] bg-gray-100 border text-gray-500 px-1 rounded ml-1 uppercase">{s.itemType}</span></td>
                                    <td className="px-4 py-3">{s.qty}</td>
                                    <td className="px-4 py-3 text-right font-bold">{currency(s.totalPrice)}</td>
                                    <td className="px-4 py-3 text-right text-green-600 font-bold">{currency(s.totalProfit)}</td>
                                    <td className="px-4 py-3 text-right"><button onClick={() => onDeleteSale(s.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                                </tr>
                            ))}
                            {sales.length === 0 && <tr><td colSpan={6} className="text-center py-8 text-gray-400">No sales recorded.</td></tr>}
                        </tbody>
                    </table>
                </div>
            </div>
          )}

          {activeTab === 'capital' && (
            <div className="space-y-6">
                <div className="bg-white p-4 rounded-xl border border-orange-100 shadow-sm flex flex-wrap gap-3 items-end">
                    <div className="flex-1"><label className="text-[10px] font-bold text-gray-500 uppercase">Item</label><input className="w-full text-sm p-2 rounded border focus:ring-orange-500" value={newCap.name} onChange={e => setNewCap({...newCap, name: e.target.value})} placeholder="Filament/Printer"/></div>
                    <div className="w-32"><label className="text-[10px] font-bold text-gray-500 uppercase">Cost</label><input type="number" className="w-full text-sm p-2 rounded border focus:ring-orange-500" value={newCap.price} onChange={e => setNewCap({...newCap, price: e.target.value})}/></div>
                    <div className="w-32"><label className="text-[10px] font-bold text-gray-500 uppercase">Category</label><select className="w-full text-sm p-2 rounded border" value={newCap.category} onChange={e => setNewCap({...newCap, category: e.target.value as any})}><option>Filament</option><option>Printer</option><option>Parts</option><option>Other</option></select></div>
                    <button onClick={handleAddCapital} className="bg-orange-600 text-white px-4 py-2 rounded font-bold text-sm hover:bg-orange-700">Add Expense</button>
                </div>
                <div className="bg-white rounded-xl border shadow-sm overflow-hidden">
                    <table className="w-full text-left">
                        <thead className="bg-gray-50 text-[10px] uppercase text-gray-400 font-bold"><tr><th className="px-4 py-3">Date</th><th className="px-4 py-3">Category</th><th className="px-4 py-3">Item</th><th className="px-4 py-3 text-right">Cost</th><th className="px-4 py-3 text-right"></th></tr></thead>
                        <tbody className="divide-y text-sm">
                            {capitalHistory.map(c => (
                                <tr key={c.id}>
                                    <td className="px-4 py-3 text-gray-500">{c.date}</td>
                                    <td className="px-4 py-3"><span className="px-2 py-0.5 rounded text-[10px] font-bold bg-orange-50 text-orange-600">{c.category}</span></td>
                                    <td className="px-4 py-3 font-medium">{c.name}</td>
                                    <td className="px-4 py-3 text-right font-bold text-red-600">{currency(c.price)}</td>
                                    <td className="px-4 py-3 text-right"><button onClick={() => onDeleteCapital(c.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button></td>
                                </tr>
                            ))}
                             {capitalHistory.length === 0 && <tr><td colSpan={5} className="text-center py-8 text-gray-400">No expenses recorded.</td></tr>}
                        </tbody>
                    </table>
                </div>
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

const StatsCard = ({ label, value, color }: any) => (
  <div className="bg-white p-4 rounded-xl border flex flex-col shadow-sm">
      <span className="text-[10px] font-bold text-gray-500 uppercase">{label}</span>
      <span className={clsx("text-xl font-bold", color)}>{value}</span>
  </div>
);

const TabBtn = ({ active, onClick, label, icon }: any) => (
  <button onClick={onClick} className={clsx("py-4 text-sm font-bold flex items-center gap-2 border-b-2 transition-all", active ? "border-brand-600 text-brand-600" : "border-transparent text-gray-400 hover:text-gray-600")}>
    {icon} {label}
  </button>
);
